INSERT INTO public.subjects(id,name,slug,description,is_active,island,mascot,character) VALUES ('3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Matematika','matematika','Pulau Numeria — bersama Kapten Rubi. Materi komik CRA kelas 1–6.',true,'Pulau Numeria','Kapten Rubi','rubi') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,is_active=true,island=EXCLUDED.island,mascot=EXCLUDED.mascot,character=EXCLUDED.character WHERE (subjects.name,subjects.description,subjects.is_active,subjects.island,subjects.mascot,subjects.character) IS DISTINCT FROM (EXCLUDED.name,EXCLUDED.description,true,EXCLUDED.island,EXCLUDED.mascot,EXCLUDED.character);
INSERT INTO public.subjects(id,name,slug,description,is_active,island,mascot,character) VALUES ('4f0111bf-ef26-57a9-8550-b3a891bb00a9','Bahasa Indonesia','bahasa-indonesia','Pulau Kata — bersama Bobo. Materi komik CRA kelas 1–6.',true,'Pulau Kata','Bobo','bobo') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,is_active=true,island=EXCLUDED.island,mascot=EXCLUDED.mascot,character=EXCLUDED.character WHERE (subjects.name,subjects.description,subjects.is_active,subjects.island,subjects.mascot,subjects.character) IS DISTINCT FROM (EXCLUDED.name,EXCLUDED.description,true,EXCLUDED.island,EXCLUDED.mascot,EXCLUDED.character);
INSERT INTO public.subjects(id,name,slug,description,is_active,island,mascot,character) VALUES ('1d86d8ef-051b-5dc0-8689-c366d8036ee7','IPA','ipa','Pulau Eksplora — bersama Ilmuwan Tobi. Materi komik CRA kelas 1–6.',true,'Pulau Eksplora','Ilmuwan Tobi','tobi') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,is_active=true,island=EXCLUDED.island,mascot=EXCLUDED.mascot,character=EXCLUDED.character WHERE (subjects.name,subjects.description,subjects.is_active,subjects.island,subjects.mascot,subjects.character) IS DISTINCT FROM (EXCLUDED.name,EXCLUDED.description,true,EXCLUDED.island,EXCLUDED.mascot,EXCLUDED.character);
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '1414608a-989f-5c0f-a9e8-057b8ec64c68',s.id,'Mengenal Angka 1–20','komik-matematika-kelas-1-bab-1',1,'A','Komik · Bab 1','dasar','published',20,'{"character":"rubi","summary":"Pulau Numeria bersama Kapten Rubi: Mengenal Angka 1–20. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Kapten Rubi","emotion":"kaget","stage":"concrete","text":"Kapten Rubi menyiapkan kartu untuk teman-teman di dermaga Numeria. Kartu berserakan membuatnya ragu apakah semua teman sudah mendapat satu. Yuk, susun dan hitung tanpa melewatkan kartu!"},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Model kelompok: satu bingkai sepuluh penuh dan empat titik lepas menyatakan 14. Benda yang sama dipindah susunannya tetap berjumlah sama."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Satu benda, satu hitungan. Sentuh atau pindahkan satu benda setiap menyebut satu bilangan. Mulailah dari satu, lalu dua, tiga, dan seterusnya. Bilangan terakhir menyatakan banyak seluruh benda. Jangan menghitung benda yang sama dua kali. Susunan boleh berjajar atau melingkar; selama tidak ada benda ditambah atau diambil, banyaknya tetap."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Pindahkan tujuh kartu ke wadah sambil menghitung. Bilangan terakhir tujuh, jadi ada 7 kartu meskipun kartunya kemudian disusun dua baris."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Belasan sebagai sepuluh dan sisanya. Buat satu kelompok berisi sepuluh benda. Bilangan sebelas sampai sembilan belas dapat dilihat sebagai sepuluh ditambah beberapa satuan. Dua puluh berarti dua kelompok sepuluh. Bentuk kelompok memudahkan pemeriksaan sehingga kamu tidak perlu selalu mengulang hitungan dari awal."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Ada 10 kartu dalam ikatan dan 6 kartu lepas. Jumlahnya 16, dibaca enam belas. Dua ikatan sepuluh berjumlah 20."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Membandingkan dan mengurutkan. Pasangkan benda dari dua kelompok satu per satu. Kelompok yang masih mempunyai sisa lebih banyak. Jika tidak ada sisa pada kedua kelompok, keduanya sama banyak. Pada urutan bilangan, maju satu langkah berarti bertambah satu dan mundur satu langkah berarti berkurang satu. Lambang bilangan menuliskan banyak itu."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Kelompok 12 memiliki dua benda tersisa saat dipasangkan dengan kelompok 10. Maka 12 lebih banyak dari 10. Urutan 14, 15, 16 selalu naik satu."},{"type":"mini_check","stage":"abstract","question":"Dua kelompok masing-masing sepuluh berisi … benda.","options":["2","10","20"],"correct_index":2,"feedback":"Hebat, kamu sudah mencoba! Dua kelompok sepuluh digabung: 10 + 10 = 20 benda."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"senang","stage":"abstract","text":"Hitungan terakhir menyatakan jumlah. Belasan tersusun dari sepuluh dan satuan. Bandingkan dengan pasangan dan urutkan menurut banyaknya. Ayo terapkan: Buat toko kartu berlabel 1–20. Pendamping memilih satu label; ambil benda sebanyak labelnya, kelompokkan sepuluh jika memungkinkan, lalu jelaskan cara memeriksa jumlah. Tukar peran dan bandingkan dua pesanan."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I"}]}'::jsonb FROM public.subjects s WHERE s.slug='matematika' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
