INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '8abd65aa-8943-52aa-8329-d49c5e83bf0b',s.id,'Penjumlahan & Pengurangan Benda','komik-matematika-kelas-1-bab-2',1,'A','Komik · Bab 2','dasar','published',20,'{"character":"rubi","summary":"Pulau Numeria bersama Kapten Rubi: Penjumlahan & Pengurangan Benda. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Kapten Rubi","emotion":"kaget","stage":"concrete","text":"Keranjang Rubi mula-mula berisi buah. Sebagian buah datang dari kebun, sebagian diberikan kepada teman. Ia ingin tahu kapan perlu menggabungkan dan kapan perlu mencari sisa."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Gambar bagian-keseluruhan: 6 kartu merah + 4 kartu biru = 10 kartu. Pada pengurangan, tandai kartu yang dipindah dan hitung yang masih ada."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Menggabungkan dua bagian. Pisahkan dua kelompok dengan warna berbeda, lalu gabungkan. Banyak seluruh benda adalah hasil penjumlahan. Tanda + dibaca tambah. Tanda = menyatakan nilai di kedua sisi sama. Menambah nol tidak mengubah jumlah karena tidak ada benda baru. Menukar urutan dua kelompok juga tidak mengubah jumlahnya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Enam kartu merah dan lima kartu biru menjadi 11 kartu. Tulis 6 + 5 = 11. Kita dapat memeriksa dengan 5 + 6 = 11."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Mengambil dan membandingkan. Pada cerita mengambil, buat kelompok awal, pindahkan bagian yang diambil, lalu hitung sisa. Tanda − dibaca kurang. Untuk mencari selisih dua kelompok, buat pasangan dan hitung yang tidak berpasangan. Jangan memilih operasi hanya dari satu kata; tanyakan apa yang terjadi dan apa yang ingin diketahui."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Ada 14 kelereng besar, empat dipindahkan. Sisanya 10: 14 − 4 = 10. Dua kelompok berisi 8 dan 5 benda mempunyai selisih 3."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Strategi dan pemeriksaan. Hitung maju untuk menambah dan mundur untuk mengurangi. Jangan menghitung posisi awal sebagai langkah tambahan. Jika mendekati sepuluh, pisahkan tambahan menjadi bagian yang melengkapi sepuluh dan sisanya. Periksa pengurangan dengan menjumlahkan sisa dan bagian yang diambil; hasilnya harus sama dengan banyak semula."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"8 + 5 dapat dipikirkan 8 + 2 + 3 = 13. Untuk memeriksa 13 − 5 = 8, hitung 8 + 5 = 13."},{"type":"mini_check","stage":"abstract","question":"Kelompok 10 dan 7 benda mempunyai selisih …","options":["3","7","10"],"correct_index":0,"feedback":"Hebat, kamu sudah mencoba! Pasangkan tujuh; tiga benda kelompok pertama tersisa."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"senang","stage":"abstract","text":"Pahami cerita, buat model, tulis operasi, hitung, dan periksa. Nol tidak menambah atau mengambil benda. Penjumlahan dapat memeriksa pengurangan. Ayo terapkan: Mainkan cerita toko. Buat dua cerita menggabungkan dan dua cerita mengambil dengan kartu. Teman menulis kalimat matematika lalu memeriksa dengan benda. Minta teman menerangkan makna setiap bilangan, bukan hanya menyebut hasil."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I"}]}'::jsonb FROM public.subjects s WHERE s.slug='matematika' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
