INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '485280e5-2c2b-5fb7-88e3-f59b4804a2a4',s.id,'Nilai Tempat Ratusan, Puluhan, Satuan','komik-matematika-kelas-2-bab-1',2,'A','Komik · Bab 1','dasar','published',20,'{"character":"rubi","summary":"Pulau Numeria bersama Kapten Rubi: Nilai Tempat Ratusan, Puluhan, Satuan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Kapten Rubi","emotion":"kaget","stage":"concrete","text":"Rubi menata persediaan menjadi kotak seratus, ikatan sepuluh, dan benda satuan. Sebuah label kehilangan angka nol. Bagaimana memastikan nilai tempatnya tidak tertukar?"},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel nilai tempat: Ratusan | Puluhan | Satuan = 4 | 0 | 7, sehingga bilangan 407. Nol menjaga tempat puluhan yang kosong."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Membentuk ratusan, puluhan, satuan. Sepuluh satuan dapat ditukar satu puluhan. Sepuluh puluhan dapat ditukar satu ratusan. Pertukaran mengubah bentuk kelompok, bukan jumlah benda. Gunakan kartu atau gambar bundel untuk menunjukkan ketiga tempat. Tuliskan tempat ratusan di kiri, puluhan di tengah, dan satuan di kanan."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Dua lembar seratus, tiga ikatan sepuluh dan empat kartu satuan menyatakan 234. Bentuk panjangnya 200 + 30 + 4."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Nilai angka bergantung tempat. Angka yang sama mempunyai nilai berbeda menurut letaknya. Dalam 343, angka 3 pertama bernilai 300, sedangkan angka 3 terakhir bernilai 3. Nol menandakan tidak ada kelompok pada tempat itu dan menjaga posisi angka lain. Saat membaca bilangan, sebut bagian ratusan, puluhan, dan satuannya dengan urut."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Bilangan 407 mempunyai empat ratusan, nol puluhan, dan tujuh satuan. Menulisnya 47 akan menghilangkan nilai ratusannya."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Mengurai dan membandingkan. Urai bilangan menjadi jumlah nilai tempat. Untuk membandingkan dua bilangan tiga angka, mulai dari ratusan. Jika sama, bandingkan puluhan; jika masih sama, bandingkan satuan. Cara ini lebih cepat daripada menghitung semua benda. Pemeriksaan dilakukan dengan membentuk kembali bundel sesuai uraian."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"352 lebih besar daripada 329: ratusannya sama-sama 3, tetapi 5 puluhan lebih banyak daripada 2 puluhan. Pada 216 dan 219, satuanlah yang menentukan."},{"type":"mini_check","stage":"abstract","question":"Sepuluh puluhan setara …","options":["100","10","20"],"correct_index":0,"feedback":"Hebat, kamu sudah mencoba! Sepuluh kelompok masing-masing sepuluh menjadi satu ratusan: 10 × 10 = 100."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"senang","stage":"abstract","text":"Satu ratusan setara sepuluh puluhan. Nilai angka ditentukan tempat, dan nol menjaga tempat yang kosong. Bandingkan dari tempat terbesar. Ayo terapkan: Buat toko bundel dengan kartu R, P, dan S. Satu anak memesan bilangan tiga angka, anak lain menguraikan dan menukar sepuluh satuan menjadi puluhan. Jelaskan bahwa jumlah tetap sama setelah pertukaran."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii"}]}'::jsonb FROM public.subjects s WHERE s.slug='matematika' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
