('597e61f0-aa63-5b37-97f0-3836c9418553'::uuid,'Tabel pesanan: A=4 ratusan,2 puluhan,8 satuan; B=4 ratusan,8 puluhan,2 satuan. Pernyataan tepat …','["A lebih besar","Sama karena angkanya sama","A=482 dan B=428","B lebih besar daripada A"]'::jsonb,'hard',3::smallint,'A=428 dan B=482. Ratusan sama, tetapi puluhan B lebih besar.'),
('2e9fc525-9c6b-5607-880f-c469891b961a'::uuid,'Rubi menulis 6 ratusan + 0 puluhan + 9 satuan menjadi 69. Perbaikannya …','["609, karena nol menjaga tempat puluhan","690, karena satuan harus nol","69 sudah benar","6009, karena nol ditambah sembarang"]'::jsonb,'hard',0::smallint,'600 + 0 + 9 = 609. Menghapus nol menjadikan 6 bernilai puluhan, bukan ratusan.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '7f10dd3a-1046-5335-8127-34a0ae90ba87',s.id,'Penjumlahan & Pengurangan Bersusun','komik-matematika-kelas-2-bab-2',2,'A','Komik · Bab 2','dasar','published',20,'{"character":"rubi","summary":"Pulau Numeria bersama Kapten Rubi: Penjumlahan & Pengurangan Bersusun. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Kapten Rubi","emotion":"kaget","stage":"concrete","text":"Toko Rubi menerima dua kiriman buku dan meminjamkan sebagian. Ia menyusun angka agar satuan bertemu satuan, lalu menukar sepuluh satuan menjadi satu puluhan ketika diperlukan."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Model kolom: R | P | S. Saat 8+7=15, tulis lima satuan dan pindahkan satu puluhan ke kolom P; jumlah benda tidak berubah."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Menata kolom dan menjumlahkan. Tuliskan satuan tepat di bawah satuan, puluhan di bawah puluhan dan ratusan di bawah ratusan. Mulai menjumlah dari satuan. Jika jumlah satuan mencapai sepuluh, tukarkan menjadi satu puluhan dan sisakan satuannya. Sertakan puluhan hasil pertukaran ketika menjumlah kolom berikutnya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Pada 158 + 126, satuan 8 + 6 = 14: tulis 4, simpan 1 puluhan. Puluhan 5 + 2 + 1 = 8. Ratusan 1 + 1 = 2. Hasil 284."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Mengurangi dengan pengelompokan ulang. Kurangi dari tempat satuan. Jika satuan yang tersedia lebih kecil daripada yang diambil, tukarkan satu puluhan menjadi sepuluh satuan. Nilai seluruh bilangan tetap sama. Jangan membalik angka kecil-besar pada tiap kolom karena itu mengubah cerita pengurangan. Catat tempat yang sudah berkurang akibat pertukaran."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Pada 243 − 118, ubah 4 puluhan menjadi 3 puluhan dan 3 satuan menjadi 13 satuan. 13 − 8 = 5, 3 − 1 = 2, 2 − 1 = 1. Hasilnya 125."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Memeriksa dengan operasi kebalikan. Jumlahkan hasil pengurangan dengan bilangan yang dikurangkan; hasilnya harus kembali ke bilangan awal. Gunakan perkiraan untuk mendeteksi kesalahan besar. Pada penjumlahan, hitung kembali dengan urutan bagian ditukar atau model nilai tempat. Jawaban soal cerita perlu menyebut satuan atau benda yang dihitung."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Untuk memeriksa 321 − 106 = 215, hitung 215 + 106 = 321. Jika hasil ratusan jauh dari perkiraan 300 − 100, periksa kembali kolomnya."},{"type":"mini_check","stage":"abstract","question":"Dalam hitung bersusun, angka satuan diletakkan …","options":["Di bawah ratusan selalu","Di bawah satuan","Acak"],"correct_index":1,"feedback":"Hebat, kamu sudah mencoba! Kolom harus sesuai nilai tempat agar operasi benar."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"senang","stage":"abstract","text":"Sejajarkan nilai tempat, mulai satuan, dan pahami pertukaran. Simpan atau pinjam adalah pengelompokan ulang dengan nilai tetap. Ayo terapkan: Gambar tabel ratusan-puluhan-satuan. Peragakan satu penjumlahan yang perlu menyimpan dan satu pengurangan yang perlu menukar puluhan. Pasanganmu menjelaskan setiap perubahan sebelum kalian menuliskan hasil bersusunnya."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii"}]}'::jsonb FROM public.subjects s WHERE s.slug='matematika' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
