('31a78a6b-4367-5091-9938-e6d72bc60ef5'::uuid,'Ada 352 kartu, sebanyak 136 dibagikan. Sisa kartu …','["224","226","488","216"]'::jsonb,'medium',3::smallint,'Tukar satu puluhan: 12−6=6, 4−3=1 puluhan, 3−1=2 ratusan.'),
