('c4c87092-fcba-5584-99f7-675fbc9b3f0a'::uuid,'Siswa menghitung 203−118 dengan membalik angka tiap kolom sehingga mendapat 115. Penjelasan tepat …','["115 benar karena 8−3=5","Hasilnya 85; perlu pengelompokan ulang","Hasilnya 321 karena tambah","Hasilnya 95 tanpa pertukaran"]'::jsonb,'hard',1::smallint,'203 dapat ditukar menjadi 1 ratusan 9 puluhan 13 satuan; 13−8=5, 9−1=8, 1−1=0.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT 'dd85e42e-f712-51f1-8b06-10c367942817',s.id,'Operasi Hitung Bilangan sampai 1.000','komik-matematika-kelas-3-bab-1',3,'B','Komik · Bab 1','sedang','published',25,'{"character":"rubi","summary":"Pulau Numeria bersama Kapten Rubi: Operasi Hitung Bilangan sampai 1.000. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Kapten Rubi","emotion":"kaget","stage":"concrete","text":"Kapal Numeria membawa buku untuk dua pos belajar. Rubi mencatat stok awal, kiriman dan buku keluar. Ia perlu menjaga nilai tempat serta memeriksa dua langkah hitungnya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Garis stok: 500 → tambah 120 → kurangi 75. Tulis makna setiap hasil antara sebelum memilih jawaban akhir."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Membaca dan membandingkan bilangan. Nilai angka ditentukan tempatnya. Urai bilangan menjadi jumlah ratusan, puluhan, dan satuan; seribu adalah sepuluh ratusan. Bandingkan dari tempat paling besar, lalu bergerak ke kanan jika nilainya sama. Nol menjaga tempat kosong dan tidak boleh dihapus sesuka hati."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"706 = 700 + 0 + 6. Bilangan 760 lebih besar daripada 706 karena puluhannya lebih besar, walaupun kedua bilangan mempunyai angka yang sama."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Menjumlahkan dan mengurangkan. Sejajarkan kolom. Pada penjumlahan, sepuluh satuan ditukar menjadi satu puluhan; pada pengurangan pertukaran dapat dibalik. Catat perubahan pada kolom yang dipakai. Kerjakan dari satuan agar pertukaran masuk ke kolom berikutnya. Gunakan operasi kebalikan untuk memeriksa, bukan mengandalkan hafalan prosedur."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"368 + 257 = 625: 8 + 7 = 15, 6 + 5 + 1 = 12 puluhan, lalu 3 + 2 + 1 = 6 ratusan. Periksa dengan 625 − 257 = 368."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Menyelesaikan masalah dua langkah. Tandai apa yang diketahui dan ditanyakan. Jika ada dua kejadian, ikuti urutannya atau buat diagram. Hitung satu langkah, tulis maknanya, lalu lanjutkan. Tanda kurung membantu menampilkan bagian yang digabung. Perkiraan menggunakan ratusan terdekat dapat memberi pemeriksaan kasar tetapi bukan mengganti hasil tepat."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Perpustakaan mempunyai 450 buku, menerima 125 buku lalu meminjamkan 80. Setelah tambahan ada 575; setelah dipinjam tersisa 495 buku. Ceritanya 450 + 125 − 80."},{"type":"mini_check","stage":"abstract","question":"Ada 240 buku, masuk 60 lalu keluar 25. Sisanya …","options":["265","275","285"],"correct_index":1,"feedback":"Hebat, kamu sudah mencoba! 240 + 60 − 25 = 300 − 25 = 275."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"senang","stage":"abstract","text":"Nilai tempat membantu membaca, membandingkan, dan berhitung. Pada cerita dua langkah, urutkan kejadian dan periksa hasil dengan cara lain. Ayo terapkan: Rancang toko buku rekaan dengan stok di bawah seribu. Catat stok awal, tambahan, dan buku keluar. Tukar catatan dengan teman untuk dihitung dan diperiksa memakai operasi kebalikan serta perkiraan."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii"}]}'::jsonb FROM public.subjects s WHERE s.slug='matematika' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
