INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT 'f62c1f6e-8e74-57e8-b5dc-c3c8b59caaf2',s.id,'Konsep Perkalian Dasar','komik-matematika-kelas-3-bab-2',3,'B','Komik · Bab 2','sedang','published',25,'{"character":"rubi","summary":"Pulau Numeria bersama Kapten Rubi: Konsep Perkalian Dasar. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Kapten Rubi","emotion":"kaget","stage":"concrete","text":"Rubi menyiapkan paket dengan isi yang sama. Ia dapat menghitung satu per satu, tetapi susunan baris dan kolom akan membantunya menjelaskan perkalian dengan lebih cepat."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Susunan 4 baris × 5 titik berisi 20 titik. Membaginya menjadi dua blok masing-masing 2 baris tidak mengubah jumlah seluruhnya."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Kelompok sama banyak. Sebuah situasi dapat dinyatakan sebagai perkalian jika setiap kelompok berisi sama banyak. Tentukan banyak kelompok dan isi tiap kelompok. Jika isinya berbeda, penjumlahan biasa lebih tepat. Menyebut satuan pada jawaban menjaga hubungan antara operasi dengan cerita."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Empat kantong masing-masing berisi tiga jeruk berarti 3 + 3 + 3 + 3 = 12, atau 4 × 3 = 12 jeruk."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Susunan baris dan kolom. Gambar benda sebagai baris yang sama panjang. Banyak seluruh benda dapat dihitung menurut baris atau kolom. Pertukaran faktor memberi hasil sama, meski makna kelompok dalam cerita dapat berbeda. Satu kelompok berisi b benda berjumlah b; kelompok kosong atau nol kelompok memberikan jumlah nol."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tiga baris masing-masing lima titik berisi 15 titik. Jika dilihat sebagai lima kolom masing-masing tiga, hasil 5 × 3 juga 15."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"berpikir","stage":"abstract","text":"Mengurai perkalian. Gunakan hasil yang sudah dikenal untuk mencari yang baru. Pecah salah satu faktor menjadi dua bagian yang mudah. Hitung hasil tiap bagian lalu gabungkan. Strategi ini disebut sifat distributif dan dapat dibuktikan dengan membagi gambar persegi panjang menjadi dua bagian tanpa kehilangan titik."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"6 × 7 = 6 × (5 + 2). Bagian pertama 30, kedua 12; total 42. Periksa dengan enam kelompok tujuh benda."},{"type":"mini_check","stage":"abstract","question":"9 × 6 dapat dihitung sebagai 9 × 5 + 9 × 1, hasilnya …","options":["45","46","54"],"correct_index":2,"feedback":"Hebat, kamu sudah mencoba! Urai enam menjadi lima dan satu: 9×5=45 dan 9×1=9, lalu 45 + 9 = 54."},{"type":"dialog","speaker":"Kapten Rubi","emotion":"senang","stage":"abstract","text":"Perkalian menggunakan kelompok sama banyak. Baris-kolom menjelaskan pertukaran faktor; penguraian faktor memudahkan perhitungan. Ayo terapkan: Susun kartu dalam empat baris yang masing-masing berisi enam. Baca menurut baris dan kolom. Tutup dua kolom lalu jelaskan bagaimana jumlah keseluruhan diperoleh dari dua bagian yang tidak saling tumpang tindih."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii"}]}'::jsonb FROM public.subjects s WHERE s.slug='matematika' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
