('813220e6-a9e0-5f0b-baa2-da65fc8fc549'::uuid,'Urutan alfabet yang tepat adalah …','["buku, batu, baca","batu, baca, buku","baca, batu, buku","baca, buku, batu"]'::jsonb,'easy',2::smallint,'Bandingkan huruf kedua dan berikutnya.'),
('d68334ef-fc65-5bb3-b1f2-ea0b806040b3'::uuid,'Judul kata pada entri kamus disebut …','["Legenda","Bait","Diameter","Lema"]'::jsonb,'easy',3::smallint,'Lema adalah bentuk kata yang menjadi entri.'),
('cdd24768-2fb8-51f5-8eca-d55efd2e013b'::uuid,'Bobo mencari membawa dalam keluarga kata dasar. Kata dasarnya …','["Bawa","Memb","Membawa-bawa selalu","Awa"]'::jsonb,'medium',0::smallint,'Awalan meN- membentuk membawa dari kata dasar bawa.'),
('e5718309-f546-5c1d-9484-8d80376b1657'::uuid,'Pada Akar masalahnya adalah jadwal yang tidak jelas, akar berarti …','["Bagian tumbuhan","Asal atau penyebab","Alat menggali","Nama buah"]'::jsonb,'medium',1::smallint,'Konteks masalah memakai makna kias penyebab.'),
('f76bb7ff-2b65-576d-91e8-3af5eed06b6d'::uuid,'Tabel daftar kata: makan, mata, meja, minum. Urutan alfabet …','["mata, makan, minum, meja","meja, makan, mata, minum","makan, mata, meja, minum","minum, meja, mata, makan"]'::jsonb,'hard',2::smallint,'Huruf m sama; bandingkan huruf kedua, lalu huruf berikutnya pada makan dan mata.'),
('ee1ade20-202e-5cbc-a0a2-e3ec8d1a227f'::uuid,'Mini kamus rapat: (1) pertemuan; (2) tidak berjarak/renggang. Pada Tutup pintu rapat agar angin tidak masuk, arti tepat …','["Makna 1","Keduanya berarti pertemuan","Tidak ada arti yang bisa dipilih","Makna 2"]'::jsonb,'hard',3::smallint,'Kalimat tentang kondisi pintu, bukan kegiatan pertemuan; konteks memilih arti kedua.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT 'efa780ca-047f-57ae-9c46-09ff1a91e43d',s.id,'Kata Sifat, Sinonim, dan Antonim','komik-bahasa-indonesia-kelas-5-bab-1',5,'C','Komik · Bab 1','sedang','published',25,'{"character":"bobo","summary":"Pulau Kata bersama Bobo: Kata Sifat, Sinonim, dan Antonim. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Bobo","emotion":"kaget","stage":"concrete","text":"Bobo ingin mendeskripsikan taman tanpa mengulang kata yang sama. Ia mencari sinonim dan antonim, lalu memeriksa apakah penggantian itu tetap cocok dengan benda dan situasinya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel kata: ramai ↔ sepi; teliti ≈ cermat. Tanda mirip tidak berarti semua kata dapat ditukar dalam semua kalimat."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Kata sifat dalam deskripsi. Kata sifat dapat menerangkan ukuran, warna, keadaan atau kualitas, misalnya panjang, hijau, tenang, dan teliti. Beberapa dapat didahului sangat atau lebih. Gunakan ciri yang dapat dijelaskan, bukan label merendahkan seseorang. Bedakan penilaian subjektif seperti indah dari ukuran yang dapat diukur seperti panjang dua meter."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Kalimat Pita merah itu panjang memakai merah untuk warna dan panjang untuk ukuran relatif. Menambahkan dibanding pita biru membuat perbandingannya lebih jelas."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Sinonim sesuai konteks. Sinonim mempunyai makna mirip tetapi tidak selalu dapat saling mengganti dalam semua kalimat. Pertimbangkan tingkat kesopanan, pasangan kata dan arti khusus. Gunakan kamus untuk memeriksa, lalu baca kembali kalimat hasil penggantian. Kata yang sekilas mirip dapat berbeda nuansa atau penggunaannya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Pandai dan cerdas berdekatan makna pada anak yang cepat memahami pelajaran. Namun besar dan agung tidak selalu dapat ditukar: sepatu agung tidak lazim untuk menggantikan sepatu besar."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Antonim dan revisi pilihan kata. Antonim menyatakan pertentangan makna, misalnya panjang-pendek atau ramai-sepi. Lawan bergantung arti kata yang sedang dipakai; ringan pada beban dapat berlawanan dengan berat, sedangkan pada pekerjaan maknanya dapat dekat mudah. Saat menyunting, pilih kata yang tepat lalu pastikan maksud dan tingkat kesantunannya tetap."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Ruang itu semula ramai, kemudian sepi setelah peserta pulang. Kedua kata mempertentangkan keadaan kegiatan/bunyi, bukan ukuran ruang."},{"type":"mini_check","stage":"abstract","question":"Antonim berat pada beban adalah …","options":["Ringan","Padat selalu","Tinggi"],"correct_index":0,"feedback":"Hebat, kamu sudah mencoba! Ringan adalah lawan berat untuk massa/beban dalam penggunaan sehari-hari."},{"type":"dialog","speaker":"Bobo","emotion":"senang","stage":"abstract","text":"Kata sifat memperjelas ciri. Sinonim perlu kecocokan konteks; antonim mempertentangkan makna yang sedang digunakan. Ayo terapkan: Pilih satu benda dan tulis lima kata deskripsi. Ganti dua kata dengan sinonim yang tetap cocok, lalu tulis kalimat antonim. Teman menjelaskan apakah penggantian mengubah nuansa atau malah membuat kalimat tidak lazim."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi"}]}'::jsonb FROM public.subjects s WHERE s.slug='bahasa-indonesia' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
