('3f3c1e2a-469e-5c63-a4df-aca48612b98b'::uuid,'Antonim ramai adalah …','["Riuh","Bising","Padat","Sepi"]'::jsonb,'easy',3::smallint,'Sepi mempertentangkan keadaan ramai.'),
('8d529467-c32c-5e4d-bd66-36d2e07431a6'::uuid,'Taman itu sepi setelah acara selesai. Antonim sepi dalam konteks ini …','["Ramai","Sunyi","Lengang","Hening"]'::jsonb,'medium',0::smallint,'Ramai berlawanan dengan keadaan sepi; pilihan lain dekat makna sepi.'),
('adac801f-29d0-5b45-9cfc-c8849a4dac00'::uuid,'Rani memeriksa tugas dengan teliti. Pengganti teliti yang cocok …','["Ceroboh","Cermat","Lalai","Asal-asalan"]'::jsonb,'medium',1::smallint,'Cermat menekankan ketelitian, bukan ketergesaan.'),
('906bf578-ce2b-56d5-a72e-115dfa177743'::uuid,'Tabel konteks: A=beban ringan; B=tugas ringan. Lawan yang sesuai …','["A panjang; B biru","Keduanya selalu gelap","A berat; B sulit jika ringan berarti mudah","A cepat; B lambat selalu"]'::jsonb,'hard',2::smallint,'Lawan kata dipilih dari makna yang digunakan, bukan satu pasangan untuk semua konteks.'),
('aad02849-21f1-527d-879f-4ae24201f467'::uuid,'Siswa mengganti sepatu besar menjadi sepatu agung karena menganggap besar dan agung selalu sinonim. Evaluasi tepat …','["Selalu tepat karena panjang huruf sama","Agung berarti ukuran sepatu pasti","Semua sinonim wajib ditukar","Tidak tepat; kecocokan konteks perlu diperiksa"]'::jsonb,'hard',3::smallint,'Agung tidak lazim sebagai ukuran sepatu; kedekatan makna tidak menjamin pemakaian sama.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '7dadb4f3-c561-5b50-bd3b-f3b498a51e17',s.id,'Kalimat Langsung & Tidak Langsung','komik-bahasa-indonesia-kelas-5-bab-2',5,'C','Komik · Bab 2','sedang','published',25,'{"character":"bobo","summary":"Pulau Kata bersama Bobo: Kalimat Langsung & Tidak Langsung. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Bobo","emotion":"kaget","stage":"concrete","text":"Bobo melaporkan ucapan teman pada hari berbeda. Ia harus menjaga siapa yang berbicara dan hari yang dimaksud, bukan hanya menghapus tanda petik."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Kartu acuan: ucapan Senin “Aku datang besok.” → yang dimaksud Selasa. Laporan Rabu tetap menyebut Selasa agar waktu tidak bergeser."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Menulis ucapan langsung. Ucapan yang ditulis persis diapit tanda petik. Bagian pengiring menyebut pembicaranya. Perhatikan kapital awal ucapan dan letak tanda baca. Gunakan kutipan hanya jika kata yang ditulis benar-benar sesuai ucapan atau merupakan dialog rekaan yang kamu tulis sendiri. Jangan mengubah pendapat orang lalu tetap menyebutnya kutipan persis."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Rani berkata, “Aku membawa buku.” Kalimat pengiring Rani berkata diikuti koma; ucapan dimulai kapital dan diapit tanda petik."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Melaporkan isi ucapan. Kalimat tidak langsung tidak memakai tanda petik untuk isi laporannya. Kata bahwa dapat menghubungkan pengiring dengan isi berita. Kata ganti perlu menyesuaikan pembicara: aku dari Rani menjadi ia ketika diceritakan orang lain. Pertanyaan dapat dilaporkan memakai kata tanya atau apakah tanpa menjadikannya perintah."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Rani berkata bahwa ia membawa buku. Pertanyaan Bimo, “Kapan kita mulai?” dapat dilaporkan Bimo bertanya kapan kegiatan dimulai, jika konteks kegiatan jelas."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Menyesuaikan waktu dan tempat. Kata sekarang, besok, di sini dan kata ganti bergantung situasi. Jika laporan dibuat pada waktu atau tempat lain, jelaskan acuannya agar makna tidak berubah. Jangan mengganti secara mekanis tanpa mengetahui siapa yang melapor dan kapan. Setelah mengubah, bandingkan pesan pokok kedua kalimat."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Ucapan pada Senin, “Aku datang besok,” dilaporkan pada Rabu menjadi Ia mengatakan akan datang pada Selasa. Kata besok saja pada Rabu akan menunjuk Kamis dan mengubah maksud."},{"type":"mini_check","stage":"abstract","question":"Mengubah kutipan orang tetapi tetap menyebut kata persis adalah …","options":["Selalu boleh","Tidak tepat","Wajib dalam laporan"],"correct_index":1,"feedback":"Hebat, kamu sudah mencoba! Kutipan langsung harus akurat; parafrasa ditandai sebagai laporan."},{"type":"dialog","speaker":"Bobo","emotion":"senang","stage":"abstract","text":"Kutipan langsung menjaga kata dan tanda petik. Laporan tidak langsung menjaga makna sambil menyesuaikan kata ganti serta acuan waktu/tempat. Ayo terapkan: Tulis dialog rekaan dua tokoh tentang meminjam buku. Ubah tiga ucapan menjadi laporan tidak langsung. Tandai perubahan kata ganti, waktu, tempat, dan tanda baca, lalu minta teman memeriksa apakah pesannya tetap."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi"}]}'::jsonb FROM public.subjects s WHERE s.slug='bahasa-indonesia' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('11421d6d-31ba-5be2-a29c-1bad056ee140'::uuid,'Penanda utama ucapan langsung dalam tulisan adalah …','["Garis bilangan","Tanda persen","Nomor halaman","Tanda petik"]'::jsonb,'easy',3::smallint,'Ucapan diapit tanda petik.'),
('8aca8d21-835f-50f2-8e8d-a69e62409dc8'::uuid,'Nina berkata, “Aku membaca.” Bentuk laporan sesuai …','["Nina berkata bahwa ia membaca.","Nina berkata bahwa aku membaca selalu.","Nina membaca bahwa berkata.","“Nina bahwa ia.”"]'::jsonb,'easy',0::smallint,'Kata aku dari Nina dilaporkan sebagai ia.'),
('f92968d4-e915-52de-8915-4c45fd376c4b'::uuid,'Dita berkata, “Aku membawa peta.” Laporan yang sesuai …','["Dita berkata bahwa aku selalu membawa peta.","Dita berkata bahwa ia membawa peta.","Peta berkata Dita membawa.","Dita membawa bahwa berkata."]'::jsonb,'medium',1::smallint,'Aku pada ucapan Dita dirujuk sebagai ia oleh pelapor lain.'),
('ad505710-aceb-5571-a449-4fdc8bee5ddd'::uuid,'Bobo hendak mengutip ucapan persis teman. Penanda tulisan yang diperlukan …','["Tanda persen","Huruf besar semua","Tanda petik dan kata yang akurat","Angka yang dikarang"]'::jsonb,'medium',2::smallint,'Kutipan langsung menjaga kata asli dan diapit tanda petik.'),
('46d77c9a-c3e4-5000-92ff-7127d512564a'::uuid,'Tabel waktu: ucapan Senin=“Besok aku datang”; dilaporkan Rabu. Acuan hari yang benar …','["Kamis","Rabu","Senin","Selasa"]'::jsonb,'hard',3::smallint,'Besok mengacu pada waktu ucapan, yaitu sehari setelah Senin, bukan sehari setelah laporan.'),
('0251be64-b531-54fc-a1e2-f3caf8c1af2a'::uuid,'Ucapan Rani: “Aku menunggu di sini.” Pelapor pindah tempat. Prinsip laporan tepat …','["Sebut Rani dan lokasi asal bila perlu agar acuan jelas","Biarkan aku dan di sini selalu tanpa cek","Ubah Rani menjadi pelapor","Tambahkan ucapan yang tak pernah ada"]'::jsonb,'hard',0::smallint,'Kata ganti dan tempat bergantung konteks; pelaporan harus menjaga maksud asli.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT 'da678bfb-eeaf-50c8-bb6c-40d08fb12263',s.id,'Ide Pokok & Kesimpulan Teks Laporan','komik-bahasa-indonesia-kelas-6-bab-1',6,'C','Komik · Bab 1','sedang','published',25,'{"character":"bobo","summary":"Pulau Kata bersama Bobo: Ide Pokok & Kesimpulan Teks Laporan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Bobo","emotion":"kaget","stage":"concrete","text":"Bobo merangkum pengamatan beberapa buku. Ia ingin menyebut temuan yang benar-benar dicatat dan tidak memperluas satu kelompok kecil menjadi seluruh sekolah."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel pengamatan: 6 buku diperiksa; 4 sampul utuh; 2 sampul rusak. Simpulan harus tetap menyebut enam buku yang diamati."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Membaca tujuan dan hasil. Temukan objek, tujuan, waktu dan cara pengumpulan data. Baca hasil sebelum menerima simpulan. Informasi tentang dua lokasi tidak otomatis mewakili seluruh daerah. Perhatikan jumlah sampel dan keterbatasan alat. Sumber data membantu pembaca menilai seberapa jauh temuan dapat digunakan."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Laporan rekaan: enam pot diamati tiga hari; empat pot bertunas. Data ini menyatakan empat dari enam pot pada pengamatan itu, bukan semua benih selalu bertunas dalam tiga hari."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Ide pokok dan rincian bukti. Tentukan gagasan yang merangkum setiap paragraf dan daftar rincian pendukungnya. Bedakan angka hasil, penafsiran dan saran. Kalimat utama bisa muncul di posisi berbeda. Buat peta gagasan agar hubungan antarparagraf terlihat, lalu cari apakah ada paragraf yang tidak mendukung tujuan."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Paragraf tentang pertumbuhan memuat tinggi hari pertama, kedua dan ketiga. Ide pokoknya perubahan pertumbuhan selama pengamatan, bukan salah satu angka hari saja."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Menyusun simpulan yang terbatas. Jawab tujuan dengan temuan paling penting dan sebut lingkup data. Jangan mengulang seluruh tabel atau memberi kepastian melebihi bukti. Jika membandingkan kelompok, jelaskan kondisi dan kemungkinan keterbatasan. Saran boleh diberikan terpisah serta diberi label, bukan dimasukkan sebagai hasil yang sudah terjadi."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Simpulan sesuai: Pada enam pot yang diamati selama tiga hari, empat menunjukkan tunas. Simpulan tidak sesuai: Semua tanaman di kota tumbuh cepat karena empat pot bertunas."},{"type":"mini_check","stage":"abstract","question":"Mencatat sampel dan waktu membantu menilai …","options":["Warna favorit","Batas kesimpulan","Kecepatan mengetik"],"correct_index":1,"feedback":"Hebat, kamu sudah mencoba! Lingkup data menentukan sejauh mana klaim didukung."},{"type":"dialog","speaker":"Bobo","emotion":"senang","stage":"abstract","text":"Periksa tujuan, metode dan hasil. Cari ide pokok setiap bagian, lalu simpulkan sesuai bukti dan batas sampel. Ayo terapkan: Amati jumlah daun pada tiga tanaman milik sendiri dengan izin dan tanpa merusak. Susun satu tabel dan dua paragraf hasil. Tulis ide pokok tiap paragraf serta simpulan yang hanya berlaku pada data pengamatan itu."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi"}]}'::jsonb FROM public.subjects s WHERE s.slug='bahasa-indonesia' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('75561632-a4b7-5087-838a-b13ef86dd24b'::uuid,'Laporan mengamati 5 buku, 2 rusak. Simpulan sesuai …','["Semua buku sekolah rusak.","Tidak ada buku rusak.","Seluruh kota kekurangan buku.","Dua dari lima buku yang diamati rusak."]'::jsonb,'easy',3::smallint,'Simpulan menjaga jumlah dan lingkup sampel.'),
('0310ea40-fe74-524d-8a8b-2df1f7b16a18'::uuid,'Ide pokok paragraf menaungi …','["Rincian dalam paragraf","Semua buku di dunia","Nama penulis saja","Harga laporan"]'::jsonb,'easy',0::smallint,'Gagasan utama menjelaskan hubungan rincian.'),
('d80045ec-ae7a-5110-be84-2b79f65df152'::uuid,'Laporan menyebut 10 pot diamati, 7 bertunas. Simpulan yang sesuai …','["Semua tanaman kota bertunas.","Tujuh dari sepuluh pot yang diamati bertunas.","Tidak ada pot bertunas.","Tujuh kota pasti hijau."]'::jsonb,'medium',1::smallint,'Simpulan mempertahankan jumlah dan lingkup objek.'),
('cb3134c1-8780-5ea6-905a-737a3b8374ee'::uuid,'Paragraf berisi tinggi tanaman hari pertama, kedua dan ketiga. Ide pokok yang sesuai …','["Warna semua gedung","Harga pupuk tanpa data","Perubahan tinggi selama pengamatan","Semua tanaman sama tinggi"]'::jsonb,'medium',2::smallint,'Ketiga rincian membahas perubahan tinggi dalam periode pengamatan.'),
('cdecd548-cee4-55bc-b3db-bd2c651cb917'::uuid,'Tabel buku: diperiksa 8; sampul utuh 5; rusak 3. Klaim “Semua buku sekolah rusak” …','["Pasti benar","Benar karena ada angka","Benar jika judul besar","Tidak didukung; data hanya delapan buku dan tiga rusak"]'::jsonb,'hard',3::smallint,'Klaim melampaui sampel dan bertentangan dengan lima sampul utuh.'),
('e26bd2c6-8cd5-53c7-8ad8-e3a55c1cc46a'::uuid,'Dua simpulan: A menyebut hasil dan waktu pengamatan; B menambah penyebab yang tidak diukur. Yang lebih dapat dipertanggungjawabkan …','["A","B karena lebih meyakinkan","Keduanya otomatis sama","B jika memakai kata pasti"]'::jsonb,'hard',0::smallint,'Simpulan harus mengikuti bukti. Dugaan penyebab perlu diberi label dan diuji terpisah.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '09c26f92-34f8-56cc-9258-e33ae3e8373b',s.id,'Menyusun Teks Pidato Persuasif','komik-bahasa-indonesia-kelas-6-bab-2',6,'C','Komik · Bab 2','sedang','published',25,'{"character":"bobo","summary":"Pulau Kata bersama Bobo: Menyusun Teks Pidato Persuasif. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Bobo","emotion":"kaget","stage":"concrete","text":"Bobo menyiapkan pidato agar buku dikembalikan tepat waktu. Ia ingin ajakan yang jelas dan berbukti, sekaligus memberi solusi bagi teman yang mengalami kesulitan."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Peta pidato: masalah → alasan/bukti → langkah konkret → penutup. Bedakan data, pendapat dan ajakan, lalu periksa sumbernya."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Tujuan, pendengar dan susunan. Pilih satu tujuan nyata, misalnya mengembalikan buku tepat waktu. Kenali pendengar dan gunakan bahasa sesuai situasi. Susun pembukaan yang mengenalkan topik, isi yang memuat masalah dan alasan, lalu penutup berisi ajakan konkret. Sapaan tidak harus panjang; yang penting tujuan jelas."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Pembukaan: Teman-teman, mari menjaga buku agar dapat dipakai bersama. Isi membahas akibat keterlambatan dan cara mengingat jadwal. Penutup mengajak memeriksa tanggal pinjam sebelum pulang."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Alasan, bukti dan tanggapan. Bedakan klaim dari alasan dan bukti. Data yang digunakan perlu sumber dan konteks; jangan membuat angka agar terdengar kuat. Pertimbangkan hambatan pendengar dan beri solusi wajar. Ajakan yang aman tidak memakai rasa takut palsu, hinaan, atau janji yang tidak dapat dipenuhi."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Alasan: pengembalian tepat waktu memberi kesempatan pembaca lain. Solusi: menulis pengingat. Hindari klaim siapa terlambat pasti tidak peduli karena dapat ada hambatan yang perlu dibantu."},{"type":"dialog","speaker":"Bobo","emotion":"berpikir","stage":"abstract","text":"Penyampaian dan revisi. Latih lafal, volume dan jeda. Kontak mata dan sikap tubuh boleh disesuaikan kebutuhan pembicara; tidak semua orang harus memakai cara yang sama. Minta umpan balik tentang kejelasan ajakan dan kekuatan alasan. Perbaiki bagian membingungkan dan cek durasi tanpa mengorbankan makna."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Ajakan Mari membawa botol isi ulang ketika memungkinkan lebih konkret daripada Kita harus sempurna. Sebut satu langkah yang dapat dicoba pendengar, lalu beri ruang pertanyaan."},{"type":"mini_check","stage":"abstract","question":"Menanggapi hambatan pendengar sebaiknya …","options":["Mengejek","Memaksa tanpa alasan","Memberi solusi wajar"],"correct_index":2,"feedback":"Hebat, kamu sudah mencoba! Solusi menghargai keadaan pendengar."},{"type":"dialog","speaker":"Bobo","emotion":"senang","stage":"abstract","text":"Pidato persuasif mempunyai tujuan, alasan berbukti dan ajakan konkret. Bahasa menghargai pendengar serta penyampaian jelas lebih kuat daripada tekanan. Ayo terapkan: Tulis pidato 1–2 menit tentang merawat ruang belajar. Tandai klaim, alasan, bukti yang benar-benar tersedia, dan ajakan. Sampaikan kepada kelompok kecil atau rekam hanya dengan persetujuan semua yang terlibat."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi"}]}'::jsonb FROM public.subjects s WHERE s.slug='bahasa-indonesia' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('21627f89-c8d2-53f9-b169-e87d179aa9bc'::uuid,'Tujuan utama pidato persuasif adalah …','["Mengajak dengan alasan","Menyembunyikan tujuan","Menghafal angka acak","Menghina lawan"]'::jsonb,'easy',0::smallint,'Persuasi mengarahkan sikap/tindakan melalui alasan.'),
('f43c42ef-23c5-53d7-882a-9dfcd4139ba8'::uuid,'Ajakan paling konkret adalah …','["Jadilah paling baik selalu.","Pisahkan kertas bekas di kotak berlabel.","Semua harus sama.","Pikirkan saja."]'::jsonb,'easy',1::smallint,'Ada tindakan dan tempat yang jelas.'),
('3641d16d-0fa3-52f1-b739-f7ed3fdf5101'::uuid,'Ajakan yang paling dapat dilakukan pendengar adalah …','["Jadilah sempurna selamanya.","Semua harus sama.","Periksa tanggal kembali buku sebelum pulang.","Pikirkan sesuatu saja."]'::jsonb,'medium',2::smallint,'Ajakan menyebut satu tindakan konkret dan waktu melakukannya.'),
('cb8af0da-d917-5d52-9949-d25917129826'::uuid,'Bobo hendak memakai angka dalam pidato. Langkah tepat …','["Buat angka sebesar mungkin","Hapus sumber agar singkat","Gunakan rumor saja","Periksa sumber, tanggal dan konteksnya"]'::jsonb,'medium',3::smallint,'Data perlu dapat ditelusuri agar menjadi bukti yang layak.'),
('0ae35c7a-ec30-5fab-966a-19977d563f7e'::uuid,'Data rekaan: 12 dari 20 peminjam mengembalikan tepat waktu. Kalimat pidato yang sesuai …','["Sebagian peminjam masih perlu dukungan pengingat","Tak seorang pun tepat waktu","Semua pasti malas","Seluruh kota terlambat"]'::jsonb,'hard',0::smallint,'Delapan belum tepat waktu, tetapi data tidak membuktikan sifat pribadi atau seluruh kota. Dukungan pengingat adalah usulan yang wajar.'),
('295bd125-91d5-53b1-a8a7-9b43b451bbf3'::uuid,'Tabel usulan: A=mengingatkan jadwal dan menyediakan bantuan; B=mengejek yang terlambat. Persuasi yang menghargai pendengar …','["B, karena hinaan selalu bukti","A, karena mengajak dengan solusi","Keduanya sama","B jika berteriak"]'::jsonb,'hard',1::smallint,'Ajakan efektif menjelaskan tindakan dan membantu hambatan, bukan merendahkan orang.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '8b7f9307-62ce-50af-8953-e5d7a611feae',s.id,'Mengenal Panca Indra Kita','komik-ipa-kelas-1-bab-1',1,'A','Komik · Bab 1','dasar','published',20,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Mengenal Panca Indra Kita. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Ilmuwan Tobi menemukan kain lembut, kartu berwarna dan bunyi ketukan pelan. Ia ingin tahu informasi mana yang diperoleh tiap indra tanpa mencicipi atau menyentuh bahan asing."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel aman: kartu → warna/bentuk → mata; kain → halus/kasar → kulit; ketukan pelan → bunyi → telinga."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Mata dan telinga mengumpulkan informasi. Mata membantu melihat warna, bentuk dan gerak dengan menerima cahaya. Telinga membantu mendengar bunyi. Pengamatan dapat memakai lebih dari satu indra, tetapi tidak harus semua. Orang dapat memakai kacamata, alat bantu dengar atau cara komunikasi berbeda; semua perlu dihargai. Jangan menatap matahari atau mendekatkan bunyi keras ke telinga."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Kartu merah dikenali melalui penglihatan. Ketukan pelan pada meja dikenali melalui pendengaran. Jika tidak melihat sumber ketukan, kita belum tahu pasti benda mana yang mengetuk."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Hidung, lidah, dan kulit. Hidung membantu mengenali bau, lidah mengenali rasa pada makanan yang aman, dan kulit merasakan sentuhan serta perubahan suhu. Rasa makanan dipengaruhi juga oleh bau. Jangan memakai indra sebagai alat menguji keselamatan bahan asing. Benda panas, cairan pembersih dan tanaman tidak dikenal tidak boleh dicoba."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Permukaan kain terasa halus melalui sentuhan kulit. Kita boleh menjelaskan rasa makanan sehari-hari yang sudah diizinkan pendamping, tetapi tidak menjilat benda untuk mengetahui namanya."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Mencatat hasil, bukan menebak. Gunakan kata yang tepat seperti merah, bulat, pelan atau halus. Pisahkan hasil yang benar-benar diamati dari dugaan. Indra dapat memiliki keterbatasan sehingga perlu alat atau pengamatan lain. Lima kelompok indra pada bab ini membantu mengenali lingkungan; tubuh juga mempunyai kemampuan merasakan keadaan lain yang dipelajari kemudian."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Benda terasa halus adalah catatan sentuhan. Benda pasti mahal bukan hasil indra itu. Dua orang dapat memakai cara berbeda untuk mengenali bentuk benda secara aman."},{"type":"mini_check","stage":"abstract","question":"Saat teman memakai alat bantu, sikap tepat …","options":["Mengejek","Menyembunyikan alat","Menghargai cara belajarnya"],"correct_index":2,"feedback":"Hebat, kamu sudah mencoba! Cara memperoleh informasi dapat berbeda dan perlu didukung."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Indra mengumpulkan informasi, bukan menjamin semua dugaan benar. Pilih cara pengamatan yang aman dan hargai perbedaan kemampuan. Ayo terapkan: Dengan pendamping, amati tiga benda aman seperti kain, kartu dan sendok tanpa bagian tajam. Catat warna/bentuk, bunyi pelan jika ada, dan tekstur. Jangan gunakan rasa atau bau bahan asing. Jelaskan indra yang dipakai pada tiap catatan."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":true,"review_status":"needs_teacher_review","curriculum_note":"Pengayaan sains Fase A; perlu review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('6917cab4-82e6-58d7-95bf-75607a838644'::uuid,'Bunyi pelan dikenali terutama dengan …','["Mata","Lidah","Telinga","Lutut"]'::jsonb,'easy',2::smallint,'Telinga menerima informasi bunyi.'),
('3a10a54f-9f00-52b9-89ff-9f2812e16438'::uuid,'Tekstur kain dikenali dengan …','["Lidah wajib","Rambut saja","Gigi","Kulit"]'::jsonb,'easy',3::smallint,'Kulit membantu merasakan sentuhan.'),
('517c00b8-4349-5c08-a6d0-551c0e4e58c1'::uuid,'Tobi ingin membedakan kartu merah dan biru. Indra yang terutama dipakai …','["Penglihatan","Pengecapan","Penciuman","Pendengaran"]'::jsonb,'medium',0::smallint,'Warna diketahui melalui informasi cahaya yang diterima mata.'),
('29d622a9-a76d-5fea-a4a6-37b60b68e7e5'::uuid,'Permukaan kain terasa halus saat diraba dengan aman. Informasi ini berasal dari …','["Lidah","Kulit","Gigi","Rambut saja"]'::jsonb,'medium',1::smallint,'Kulit membantu mengenali tekstur melalui sentuhan.'),
('7f3f6780-9138-5d35-9539-d1d4638d5db0'::uuid,'Tabel catatan: A=kartu berwarna hijau; B=kartu pasti mahal. Catatan indra yang dapat langsung didukung …','["B saja","Keduanya","A saja","Tidak ada warna yang dapat diamati"]'::jsonb,'hard',2::smallint,'Hijau adalah pengamatan visual; harga perlu informasi lain dan tidak diketahui dari warna.'),
('bd00f7cd-0bcb-565e-8be0-ad0dc67d5916'::uuid,'Tobi menemukan cairan tak dikenal. Pilihan A=mencicipi untuk tahu; B=tidak menyentuh dan bertanya pendamping. Pilihan ilmiah yang aman …','["A","Keduanya wajib","A asal sedikit","B"]'::jsonb,'hard',3::smallint,'Pengamatan tidak boleh mengorbankan keselamatan; bahan asing tidak diuji dengan mulut atau dicium dekat-dekat.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '1c74fdd8-2f01-5298-8806-bba47e5f044d',s.id,'Merawat Tubuh & Kesehatan Gigi','komik-ipa-kelas-1-bab-2',1,'A','Komik · Bab 2','dasar','published',20,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Merawat Tubuh & Kesehatan Gigi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Tobi membuat jadwal kebiasaan sehat untuk tokoh komik. Ia belajar merawat gigi dengan lembut dan meminta bantuan saat ada masalah, bukan menilai atau mempermalukan kondisi tubuh teman."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Kartu kebiasaan: sesudah toilet → cuci tangan; setelah sarapan dan sebelum tidur → sikat gigi sesuai arahan pendamping; keluhan → minta bantuan."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Kebersihan tangan dan tubuh. Tangan dapat membawa kotoran yang tidak selalu terlihat. Cuci tangan memakai sabun dan air bersih sesuai petunjuk pendamping, terutama sebelum makan dan setelah dari toilet. Bersihkan tubuh dan ganti pakaian kotor. Gunakan alat pribadi dengan benar; jangan mencampur cairan pembersih atau memasukkannya ke mulut."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Sesudah bermain tanah, tangan tampak kotor. Walau kotoran sudah tidak terlihat, mencuci dengan sabun tetap merupakan kebiasaan penting sebelum memegang makanan."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Gigi, makanan dan perawatan. Gigi membantu menggigit serta mengunyah. Sisa makanan dan plak perlu dibersihkan dengan menyikat gigi memakai sikat dan pasta gigi sesuai usia serta arahan pendamping/dokter gigi. Anjuran kebiasaan menyikat dua kali sehari mencakup setelah sarapan dan sebelum tidur. Jangan menelan pasta gigi. Pemeriksaan gigi dilakukan bersama orang dewasa."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tokoh menyikat seluruh permukaan gigi dengan lembut dan membersihkan alatnya. Menyikat sangat keras bukan berarti lebih bersih dan dapat mengganggu gusi."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Kebiasaan seimbang dan meminta bantuan. Makanan beragam, minum air sesuai kebutuhan, istirahat dan aktivitas fisik mendukung tubuh. Tidak perlu membandingkan bentuk tubuh atau kemampuan teman. Bila merasa sakit atau menemukan gigi bermasalah, beri tahu pendamping agar dibantu tenaga kesehatan. Jangan memakai obat milik orang lain atau melakukan percobaan pada tubuh."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Jika gigi terasa sakit, tokoh menceritakan kepada pendamping dan meminta pemeriksaan. Ia tidak mencoba mencabut sendiri atau menganggap semua nyeri mempunyai penyebab sama."},{"type":"mini_check","stage":"abstract","question":"Kondisi tubuh teman yang berbeda perlu …","options":["Dihargai","Diejek","Dibandingkan untuk menghina"],"correct_index":0,"feedback":"Hebat, kamu sudah mencoba! Perbedaan tidak boleh menjadi bahan merendahkan."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Merawat diri berarti kebersihan, perawatan gigi, kebiasaan seimbang dan meminta bantuan saat perlu. Bantuan orang lain bukan tanda gagal. Ayo terapkan: Buat kartu urutan kebiasaan bersih untuk tokoh rekaan: sesudah toilet, sebelum makan, setelah sarapan dan menjelang tidur. Peragakan menyikat pada gambar/model, bukan memaksa pemeriksaan mulut teman."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":true,"review_status":"needs_teacher_review","curriculum_note":"Pengayaan sains Fase A; perlu review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"},{"title":"Kemenkes — Cara Mencegah Penyakit Gigi dan Mulut","url":"https://ayosehat.kemkes.go.id/cara-mencegah-penyakit-gigi-dan-mulut"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('679f3d98-856a-577f-929f-89efa7d720ef'::uuid,'Sebelum makan, kebiasaan yang tepat adalah …','["Mengusap pada baju saja","Menyentuh lantai","Berbagi sikat gigi","Mencuci tangan dengan sabun dan air bersih"]'::jsonb,'easy',3::smallint,'Mencuci membantu membersihkan tangan.'),
('f48422f2-2d37-59cc-9bc6-831be69bd622'::uuid,'Gigi membantu …','["Mengunyah makanan","Mendengar","Melihat cahaya","Memompa darah"]'::jsonb,'easy',0::smallint,'Gigi memotong dan menghaluskan makanan.'),
('7618a5e7-85e2-5b95-8408-e8a54f5c21b9'::uuid,'Sesudah bermain tanah, Tobi akan makan. Langkah tepat …','["Mengusap tangan pada baju saja","Mencuci tangan dengan sabun dan air bersih","Langsung memegang makanan","Menjilat tangan"]'::jsonb,'medium',1::smallint,'Mencuci membantu membersihkan kotoran yang terlihat maupun tidak terlihat.'),
('0a8145ec-9fde-5f68-b0da-d7b918dd4204'::uuid,'Tokoh merasa giginya sakit. Tindakan yang tepat …','["Mencabut sendiri","Memakai obat teman","Beri tahu pendamping agar mendapat bantuan","Menyembunyikan terus"]'::jsonb,'medium',2::smallint,'Pemeriksaan dan penanganan dibantu orang dewasa/tenaga kesehatan, bukan ditebak dari komik.'),
('8786acd6-f7c7-5f78-b257-acd73ea964eb'::uuid,'Tabel cara menyikat: A=lembut sesuai arahan; B=sekeras mungkin sampai gusi sakit. Penilaian tepat …','["B selalu lebih baik","Keduanya harus sampai sakit","Tidak perlu membersihkan gigi","A lebih tepat; keras tidak berarti lebih bersih"]'::jsonb,'hard',3::smallint,'Tekanan berlebihan bukan tujuan perawatan. Ikuti arahan pendamping/dokter gigi dan alat sesuai usia.'),
('d6f48fe5-249b-5b62-bd46-7660fb3fcb12'::uuid,'Catatan dua tokoh: A tangannya tampak bersih, B tampak kotor. Sebelum makan …','["Keduanya tetap perlu kebiasaan cuci tangan yang benar","Hanya B perlu, kuman selalu terlihat","A boleh berbagi sikat gigi","B harus dicela"]'::jsonb,'hard',0::smallint,'Kotoran/kuman tidak semuanya terlihat. Kebiasaan kebersihan tidak boleh menjadi alasan mengejek.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT 'f8cfc1ef-ed3b-55e1-8bfd-fb4b91541778',s.id,'Benda Padat, Cair, dan Gas','komik-ipa-kelas-2-bab-1',2,'A','Komik · Bab 1','dasar','published',20,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Benda Padat, Cair, dan Gas. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Tobi memindahkan air ke wadah lebar dan sebuah penghapus ke kotak lain. Tinggi air berubah, tetapi apakah jumlahnya otomatis berubah? Ia menyiapkan catatan agar bentuk tidak tertukar dengan volume."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel benda: penghapus → bentuk relatif tetap; air → mengikuti wadah dengan volume relatif tetap; udara → mengisi ruang yang tersedia."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Bentuk dan volume benda padat. Benda padat pada kondisi biasa mempunyai bentuk dan volume yang relatif tetap. Dipindah ke wadah lain tidak otomatis mengikuti seluruh bentuk wadah. Padat dapat keras atau lunak; sifat padat tidak berarti selalu berat. Benda dapat diubah bentuknya dengan gaya, dipotong atau dipanaskan, tetapi cara itu perlu mempertimbangkan keselamatan."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Penghapus dipindahkan dari kotak ke gelas tetap berbentuk penghapus. Spons dapat ditekan tetapi tetap contoh benda padat berpori."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Benda cair mengikuti wadah. Cair mempunyai volume relatif tetap tetapi bentuknya mengikuti bagian wadah yang ditempati. Air mengalir dan permukaan tenangnya mendatar di bawah pengaruh gravitasi. Wadah berbeda dapat membuat permukaan terlihat lebih tinggi atau rendah tanpa mengubah jumlah air. Jangan menyimpulkan gelas tinggi selalu berisi lebih banyak."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Air 100 mL dari gelas sempit dituang ke mangkuk lebar tetap sekitar 100 mL jika tidak tumpah. Bentuk dan tinggi permukaan berubah, volumenya tidak."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Gas mengisi ruang. Gas tidak mempunyai bentuk dan volume tetap seperti padat/cair; gas dapat mengisi ruang yang tersedia serta dimampatkan lebih mudah. Udara adalah campuran gas dan tetap ada walau tidak terlihat. Gas berbeda dari asap yang mengandung partikel. Jangan meniup balon sampai pecah dekat wajah atau menggunakan kantong untuk menutup kepala."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Botol yang tampak kosong sebenarnya berisi udara. Gelembung yang keluar saat botol dimiringkan dalam air menunjukkan adanya udara, jika diperagakan aman oleh pendamping."},{"type":"mini_check","stage":"abstract","question":"Cara belajar yang aman adalah …","options":["Menggunakan bahan dikenal dengan pendamping","Menghirup gas asing","Memanaskan botol tertutup"],"correct_index":0,"feedback":"Hebat, kamu sudah mencoba! Percobaan harus menghindari bahaya bahan dan tekanan."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Padat relatif tetap bentuk/volume; cair mengikuti wadah dengan volume relatif tetap; gas mengisi ruang tersedia. Ukuran tampilan bukan selalu banyak materi. Ayo terapkan: Pendamping memindahkan penghapus dan menuang air antara dua wadah aman. Catat apa yang berubah dan tetap. Gunakan gambar balon untuk membahas udara; tidak perlu mencicipi bahan atau melakukan percobaan gas dari bahan kimia."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":true,"review_status":"needs_teacher_review","curriculum_note":"Pengayaan sains Fase A; perlu review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('9d83de9f-555d-5f27-8e62-15793ac67549'::uuid,'Benda cair adalah …','["Batu","Pensil","Udara","Air"]'::jsonb,'easy',3::smallint,'Air dalam kondisi biasa berwujud cair.'),
('6f50526e-26f1-58af-a9c6-9e4576d1ab5a'::uuid,'Udara termasuk …','["Gas","Padat","Cair selalu","Tidak ada materi"]'::jsonb,'easy',0::smallint,'Udara adalah campuran gas yang menempati ruang.'),
('c5839796-7b07-52c0-820b-013220646c56'::uuid,'Air 100 mL dipindah tanpa tumpah ke mangkuk. Volumenya kira-kira …','["Pasti 200 mL","Tetap 100 mL","Pasti nol","Sama dengan tinggi mangkuk"]'::jsonb,'medium',1::smallint,'Memindah wadah mengubah bentuk, bukan otomatis jumlah air.'),
('48141b2a-b24e-5ee9-8fb6-9e10d128f2e3'::uuid,'Botol yang tampak kosong di ruang kelas sebenarnya berisi …','["Tidak ada materi sama sekali","Api","Udara","Air padat selalu"]'::jsonb,'medium',2::smallint,'Udara adalah campuran gas yang menempati ruang walau tak terlihat.'),
('fedb1336-f1cb-5139-bd98-133c0a471e3c'::uuid,'Tabel uji: benda A bentuk tetap saat dipindah; B bentuk mengikuti wadah, volume tetap. Model wujud yang paling sesuai …','["A gas, B padat","A cair, B gas","Keduanya bukan materi","A padat, B cair"]'::jsonb,'hard',3::smallint,'Gunakan ciri bentuk dan volume bersama, bukan warna atau ukuran.'),
('9d4c38e2-68f6-504e-8257-ec56bde0b204'::uuid,'Dua gelas berisi air sama banyak: A sempit-tinggi, B lebar-rendah. Kesimpulan tepat …','["Tinggi permukaan saja tidak membuktikan volume berbeda","A selalu lebih banyak","B selalu nol","Air berubah jenis di B"]'::jsonb,'hard',0::smallint,'Bentuk wadah memengaruhi tinggi permukaan. Bandingkan volume dengan ukuran yang sama.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '10d75f2c-13af-5897-8e69-e63508da8837',s.id,'Bagian-Bagian Tumbuhan & Fungsinya','komik-ipa-kelas-2-bab-2',2,'A','Komik · Bab 2','dasar','published',20,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Bagian-Bagian Tumbuhan & Fungsinya. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Tobi memberi label bagian tanaman pada gambar, lalu menghubungkannya dengan kebutuhan hidup. Ia tidak mencabut tanaman teman untuk melihat akar dan tidak menganggap tanah adalah makanan jadi."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Diagram alur: akar menyerap air/mineral → batang mengangkut → daun menerima cahaya untuk membuat gula; bunga/buah/biji terkait perkembangbiakan pada tumbuhan berbunga."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Akar dan batang. Akar menambatkan tumbuhan serta menyerap air dan mineral. Pada sebagian tumbuhan akar juga menyimpan cadangan. Batang menopang bagian tumbuhan dan menjadi jalur pengangkutan. Air/mineral bergerak dari akar menuju bagian lain, sedangkan hasil fotosintesis disalurkan ke bagian yang membutuhkan. Akar bukan mulut yang memakan seluruh tanah."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Batang membantu daun mendapat posisi menerima cahaya. Wortel merupakan contoh akar yang menyimpan cadangan, tetapi tidak semua akar membesar seperti wortel."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Daun dan pembuatan makanan. Daun banyak tumbuhan hijau menerima cahaya untuk fotosintesis. Tumbuhan menggunakan air dan karbon dioksida untuk membuat gula dengan bantuan energi cahaya; oksigen dihasilkan. Permukaan daun mempunyai struktur pertukaran gas. Jangan menyimpulkan semua daun harus hijau terang atau hanya daun yang pernah menjalankan fotosintesis."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tanaman di tempat sesuai kebutuhan cahayanya dapat tumbuh. Menutup seluruh daun terus-menerus dapat mengganggu proses, sehingga pengamatan tidak perlu merusak atau menahan kebutuhan tanaman."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Bunga, buah dan biji. Pada tumbuhan berbunga, bunga berkaitan dengan perkembangbiakan. Setelah proses yang sesuai, bagian bunga dapat berkembang menjadi buah yang melindungi biji. Biji dapat tumbuh menjadi tumbuhan baru bila syaratnya sesuai. Tidak semua bunga menghasilkan buah dan tidak semua tumbuhan berkembang biak hanya melalui biji."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Biji kacang dapat berkecambah pada kondisi sesuai. Tumbuhan pisang juga dapat diperbanyak melalui tunas, sehingga biji bukan satu-satunya cara tumbuhan bertambah."},{"type":"mini_check","stage":"abstract","question":"Mengamati akar tanaman milik orang lain sebaiknya …","options":["Dicabut langsung","Dengan gambar atau izin, tanpa mencabut sembarang","Dipotong diam-diam"],"correct_index":1,"feedback":"Hebat, kamu sudah mencoba! Pengamatan tidak harus merusak organisme."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Akar, batang, daun dan alat perkembangbiakan saling mendukung. Bagian dan cara tumbuh bervariasi menurut jenis tumbuhan. Ayo terapkan: Gambar satu tanaman berbunga yang dikenal, beri label akar-batang-daun-bunga/buah bila ada, dan hubungkan fungsi dengan panah. Jika bagian tidak terlihat, tulis belum diamati alih-alih mencabut tanaman."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":true,"review_status":"needs_teacher_review","curriculum_note":"Pengayaan sains Fase A; perlu review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('7a714558-305b-5183-934f-c465a1f6cb97'::uuid,'Bagian yang menyerap air dan mineral adalah …','["Akar","Bunga saja","Buah saja","Biji kering saja"]'::jsonb,'easy',0::smallint,'Akar mempunyai fungsi penyerapan pada banyak tumbuhan.'),
('b598d272-0837-5dd2-9064-2343ee0a85f6'::uuid,'Batang membantu …','["Mendengar suara","Menopang dan mengangkut bahan","Mengunyah tanah","Membuat batu"]'::jsonb,'easy',1::smallint,'Batang menopang bagian serta menjadi jalur angkutan.'),
('1091f801-65c8-5ae6-9f9c-aa5c589ea00a'::uuid,'Tanaman memerlukan air dari lingkungan akar. Bagian yang terutama menyerap air/mineral …','["Buah saja","Bunga saja","Akar","Kelopak saja"]'::jsonb,'medium',2::smallint,'Akar menambatkan tumbuhan serta membantu penyerapan air dan mineral.'),
('47801468-6538-56f2-9b49-c3550d6cd007'::uuid,'Tobi melihat biji di dalam buah. Fungsi buah yang sesuai …','["Mengunyah tanah","Mendengar bunyi","Menggantikan semua akar","Melindungi biji pada banyak tumbuhan berbunga"]'::jsonb,'medium',3::smallint,'Buah terkait perkembangan bunga dan dapat melindungi biji.'),
('8312b22d-8620-5fce-967c-e55014f8b24c'::uuid,'Tabel label: A=daun membuat gula dengan bantuan cahaya; B=akar memakan tanah utuh sebagai nasi. Label yang benar …','["A; B perlu diperbaiki","B; A salah","Keduanya benar","Keduanya tak ada hubungannya"]'::jsonb,'hard',0::smallint,'Tumbuhan membuat gula melalui fotosintesis; akar menyerap air/mineral, bukan tanah sebagai makanan jadi.'),
('5907d71e-6942-5094-b465-e8af4ffc5fdb'::uuid,'Gambar tanaman belum menunjukkan bunga. Kesimpulan tepat …','["Pasti bukan tumbuhan","Bunga belum diamati; tidak boleh langsung menyimpulkan semua tanaman tak berbunga","Pasti tak pernah berkembang biak","Harus dicabut untuk membuktikan"]'::jsonb,'hard',1::smallint,'Tahap hidup dan jenis berbeda. Tidak terlihat pada satu pengamatan bukan berarti tidak pernah ada.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '0467e497-1d90-5ab7-9e46-bfb7fddced67',s.id,'Ciri-Ciri Makhluk Hidup','komik-ipa-kelas-3-bab-1',3,'B','Komik · Bab 1','sedang','published',25,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Ciri-Ciri Makhluk Hidup. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Tobi membandingkan tanaman, batu dan mobil mainan. Mainan bergerak ketika didorong, sementara biji tampak diam. Ia perlu beberapa bukti agar tidak menyebut gerak sebagai satu-satunya tanda hidup."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel bukti: tanaman tumbuh dan merespons; mobil mainan berpindah karena dorongan; biji dapat dorman. Gunakan gabungan proses kehidupan."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Tumbuh dan membutuhkan bahan/energi. Makhluk hidup membutuhkan bahan dan energi untuk menjalankan proses tubuhnya. Hewan makan, tumbuhan hijau membuat gula dengan fotosintesis. Pertumbuhan adalah perubahan ukuran/masa yang terkait proses kehidupan, bukan sekadar benda ditumpuk. Kondisi dan laju pertumbuhan berbeda antarjenis dan tahap hidup."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Anak tanaman bertambah daun dan tinggi. Tumpukan pasir membesar karena ditambah dari luar, sehingga pertambahan besar itu bukan bukti pasir hidup."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Bernapas, bergerak dan merespons. Organisme melakukan pertukaran gas atau proses lain yang berkaitan dengan respirasi. Tumbuhan juga bernapas, tidak hanya hewan. Gerak dapat berupa perpindahan, pertumbuhan ke arah tertentu, atau perubahan bagian tubuh. Respons terhadap cahaya/sentuhan menunjukkan hubungan organisme dengan lingkungan, tetapi percobaan tidak boleh merusak."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tumbuhan dapat tumbuh condong ke arah cahaya sesuai jenis dan kondisi. Mobil bergerak karena mesin tidak otomatis hidup karena tidak mempunyai seluruh proses kehidupan sebagai organisme."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Berkembang biak dan melihat kumpulan ciri. Perkembangbiakan menghasilkan individu baru dan menjaga kelangsungan jenis. Tidak semua individu sedang atau dapat berkembang biak, sehingga ciri tersebut dipahami pada daur hidup/jenis, bukan tes tunggal setiap individu. Gunakan gabungan ciri dan sumber yang tepat untuk mengelompokkan. Biji dorman dapat tampak tidak aktif tetapi masih hidup."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Telur hewan atau biji tidak selalu memperlihatkan gerak yang mudah dilihat. Pengamatan sekali tidak cukup untuk menyatakan semuanya benda mati."},{"type":"mini_check","stage":"abstract","question":"Cara menyimpulkan ciri hidup yang baik …","options":["Hanya satu foto","Memakai beberapa bukti dan sumber","Hanya ukuran"],"correct_index":1,"feedback":"Hebat, kamu sudah mencoba! Kumpulan bukti mengurangi salah klasifikasi."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Gunakan beberapa proses kehidupan dan rentang waktu yang sesuai. Bedakan belum terlihat dari tidak ada, serta organisme dari benda yang hanya bergerak. Ayo terapkan: Buat tabel tanaman, kucing dari gambar, batu dan sepeda. Isi ciri hidup dengan bukti yang dapat dilihat atau dipelajari dari sumber. Gunakan belum diamati untuk hal yang tidak terlihat; jangan mengarang hasil percobaan."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi"},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('6805ef75-50f8-5bdc-b46a-6caafeb86cb9'::uuid,'Tumbuhan termasuk hidup karena …','["Menjalankan proses kehidupan","Selalu berjalan","Tidak bernapas","Makan tanah utuh"]'::jsonb,'easy',0::smallint,'Tumbuhan tumbuh, merespons, berespirasi dan menjalankan proses hidup.'),
('763a7a82-828b-543f-ae95-285f93d8400b'::uuid,'Pasir ditumpuk makin besar. Ini …','["Pasti hidup","Bukan bukti pertumbuhan organisme","Bukti berkembang biak","Bukti fotosintesis"]'::jsonb,'easy',1::smallint,'Pasir bertambah dari luar tanpa proses organisme.'),
('928037d2-86b8-5155-ab2d-5475f9a91ae5'::uuid,'Mobil mainan bergerak setelah didorong. Apakah gerak itu cukup membuktikan mainan hidup?','["Ya selalu","Ya jika cepat","Tidak","Ya jika berwarna hijau"]'::jsonb,'medium',2::smallint,'Benda tak hidup juga dapat bergerak; perlu proses kehidupan lain sebagai bukti.'),
('b7d987dc-1e7f-50e6-98d5-93f814c449d4'::uuid,'Biji belum berkecambah pada satu pengamatan. Kesimpulan hati-hati …','["Pasti mati","Pasti menjadi batu","Tidak membutuhkan kondisi apa pun","Bisa masih hidup dan dorman"]'::jsonb,'medium',3::smallint,'Biji dapat belum aktif tumbuh dan memerlukan kondisi sesuai; diam bukan bukti mati.'),
('a74b1aa5-8a05-57a0-b735-b7de1c6750a1'::uuid,'Tabel: A bertambah besar karena pasir dituang; B tanaman menambah daun. Bukti pertumbuhan organisme …','["B, karena terkait proses hidup","A saja","Keduanya pasti organisme","Tidak ada tanaman hidup"]'::jsonb,'hard',0::smallint,'Tumpukan bertambah dari luar berbeda dari pertumbuhan melalui proses kehidupan.'),
('356910b1-da4d-537a-bfa0-33f45c2eaf30'::uuid,'Catatan: daun mengarah ke cahaya, akar bertambah, tanaman memerlukan air. Kesimpulan paling didukung …','["Tanaman hanya hidup jika berjalan","Ada beberapa bukti proses kehidupan","Tanaman tidak berespirasi","Semua benda hijau pasti hidup"]'::jsonb,'hard',1::smallint,'Pertumbuhan, kebutuhan dan respons bersama mendukung identifikasi makhluk hidup.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '08e4c51a-ccaa-56a1-a3f9-ff3b0c343bc9',s.id,'Siklus Hidup Hewan (Metamorfosis)','komik-ipa-kelas-3-bab-2',3,'B','Komik · Bab 2','sedang','published',25,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Siklus Hidup Hewan (Metamorfosis). Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Album Tobi mencampur gambar ulat, pupa, kupu-kupu dan nimfa belalang. Ia ingin menyusun urutan dan membedakan dua pola metamorfosis tanpa menangkap hewan."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Dua jalur: kupu-kupu = telur → larva → pupa → dewasa; belalang = telur → nimfa → dewasa. Panah dewasa ke telur berarti generasi berikutnya."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Metamorfosis sempurna. Pada serangga seperti kupu-kupu, tahapnya telur, larva, pupa, dewasa. Larva dan dewasa dapat berbeda bentuk, makanan dan tempat hidup. Pupa bukan hewan mati atau sekadar tidur; perubahan berlangsung di dalamnya. Urutan gambar dapat berbentuk lingkaran karena individu dewasa menghasilkan telur generasi baru."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Telur kupu-kupu menetas menjadi ulat, ulat menjadi pupa, lalu kupu-kupu dewasa keluar. Ulat tidak mempunyai sayap seperti kupu-kupu dewasa."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Metamorfosis tidak sempurna. Pada belalang, tahapnya telur, nimfa, dewasa; tidak ada tahap pupa. Nimfa mirip dewasa tetapi lebih kecil dan belum memiliki seluruh ciri dewasa. Pergantian kulit terjadi selama pertumbuhan. Istilah tidak sempurna adalah nama pola perkembangan, bukan penilaian bahwa hewannya kurang baik."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Nimfa belalang mempunyai bentuk dasar seperti belalang dewasa, tetapi sayapnya belum berkembang penuh. Diagramnya tidak boleh ditambah kepompong."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Membandingkan siklus dan kebutuhan. Bandingkan jumlah tahap, perubahan bentuk dan kebutuhan di tiap tahap. Katak mempunyai telur, berudu dan tahap peralihan menuju dewasa, berbeda dari pola empat tahap serangga. Gangguan habitat pada satu tahap dapat memengaruhi kelangsungan populasi. Jangan menyamakan semua anak hewan dengan miniatur dewasanya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Berudu umumnya hidup di air dan menggunakan insang pada tahap awal, sedangkan katak dewasa mempunyai cara bernapas berbeda. Lingkungan yang dibutuhkan sepanjang daur hidup perlu dijaga."},{"type":"mini_check","stage":"abstract","question":"Siklus hidup perlu dipahami bersama …","options":["Warna buku saja","Harga pakan selalu","Kebutuhan dan habitat tiap tahap"],"correct_index":2,"feedback":"Hebat, kamu sudah mencoba! Tahap berbeda dapat membutuhkan kondisi berbeda."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Metamorfosis sempurna mempunyai pupa, tidak sempurna tidak. Tahap dan kebutuhan berbeda menurut jenis; jaga habitat seluruh tahap. Ayo terapkan: Susun kartu tahap kupu-kupu dan belalang. Hubungkan dengan panah lalu beri catatan bentuk serta kebutuhan. Jelaskan bahwa panah dari dewasa ke telur berarti reproduksi generasi berikutnya, bukan satu hewan berubah kembali menjadi telur."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi"},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('6833bb62-f674-55f6-b9aa-a71c77061326'::uuid,'Urutan kupu-kupu yang tepat …','["Telur-pupa-larva-dewasa","Telur-larva-pupa-dewasa","Dewasa-larva-telur-pupa","Larva-telur-dewasa-pupa"]'::jsonb,'easy',1::smallint,'Empat tahap berurutan tersebut merupakan metamorfosis sempurna.'),
('134ff612-6aa2-583d-885d-10748caf71f4'::uuid,'Tahap yang tidak ada pada belalang adalah …','["Telur","Nimfa","Pupa","Dewasa"]'::jsonb,'easy',2::smallint,'Belalang mengalami metamorfosis tidak sempurna.'),
('ec542bdc-5b44-5f7c-a1ac-da7c53df9b0b'::uuid,'Dalam album kupu-kupu, tahap setelah ulat adalah …','["Nimfa belalang","Telur kembali langsung","Berudu","Pupa"]'::jsonb,'medium',3::smallint,'Ulat adalah larva, kemudian menjadi pupa sebelum dewasa.'),
('95eb17c4-6436-539c-98d9-9912a370fd5e'::uuid,'Tobi menyusun siklus belalang. Tahap yang perlu dipakai setelah telur …','["Nimfa","Pupa","Ulat kupu-kupu","Berudu"]'::jsonb,'medium',0::smallint,'Belalang berkembang melalui telur-nimfa-dewasa tanpa pupa.'),
('e7da6dbf-0481-54ed-964d-6f91fc2d0cb5'::uuid,'Tabel album: A=kupu-kupu tanpa pupa; B=belalang tanpa pupa. Penilaian tepat …','["Keduanya benar","A kurang satu tahap; B sesuai","Keduanya wajib pupa","A sesuai, B salah"]'::jsonb,'hard',1::smallint,'Kupu-kupu mengalami pupa, sedangkan belalang tidak mempunyai tahap pupa.'),
('d8c9bbd9-665c-5e22-8052-25a17da34533'::uuid,'Diagram dewasa → telur pada siklus hidup berarti …','["Individu dewasa berubah kembali menjadi telur","Semua dewasa mati menjadi batu","Dewasa menghasilkan telur generasi berikutnya","Pupa selalu tidur tanpa perubahan"]'::jsonb,'hard',2::smallint,'Siklus menunjukkan keberlanjutan generasi, bukan satu individu kembali ke awal sebagai telur.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '5fd73be1-c9f3-5b92-b766-50deb1220b4d',s.id,'Rahasia Dapur Hijau: Bagaimana Tumbuhan Memasak?','komik-ipa-kelas-4-bab-1',4,'B','Komik · Bab 1','sedang','published',25,'{"character":"tobi","summary":"Menyelidiki cara tumbuhan hijau membuat makanan melalui fotosintesis, peran cahaya dan klorofil, serta membaca bukti percobaan sederhana.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Halo Peneliti Cilik! Pernahkah kamu melihat pohon mangga pergi ke warung untuk membeli makanan? Tentu tidak! Dari mana pohon mendapat makanan supaya bisa tumbuh besar?"},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Diagram dapur daun: akar menyerap air → batang mengangkut air ke daun; daun menerima karbon dioksida dan cahaya. Fotosintesis menghasilkan makanan berupa gula dan oksigen."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Dapur hijau dan penangkap cahaya. Tumbuhan hijau membuat makanan melalui fotosintesis. Klorofil adalah zat warna hijau yang membantu menangkap cahaya, bukan nama dapur atau makanan. Proses ini memerlukan air dan karbon dioksida dengan bantuan energi cahaya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Bayangkan daun sebagai dapur dan klorofil sebagai penangkap cahaya: cahaya membantu proses air + karbon dioksida → gula + oksigen. Cahaya adalah sumber energi, bukan bahan makanan yang diserap akar."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Perjalanan air dan hasil fotosintesis. Akar menyerap air dan mineral dari tanah. Air diangkut melalui batang ke daun. Gula hasil fotosintesis digunakan tumbuhan untuk tumbuh dan dapat disimpan; oksigen dilepaskan. Tumbuhan juga bernapas, baik siang maupun malam."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Kartu alur: tanah → akar → batang → daun. Kartu hasil: gula untuk tumbuhan dan oksigen yang juga diperlukan manusia untuk bernapas. Karbon dioksida adalah gas bahan fotosintesis, bukan nama lain udara kotor atau panas."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Membaca bukti dengan hati-hati. Untuk menyelidiki pengaruh cahaya, bandingkan tumbuhan sejenis dengan ukuran awal, air, tanah dan lama pengamatan yang sama. Ubah hanya kondisi cahaya. Daun layu saja belum membuktikan penyebabnya, karena air dan keadaan lain juga bisa berpengaruh."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Data rekaan percobaan pelepasan gas tumbuhan air selama 5 menit: terang 18 gelembung, redup 6, gelap 0. Dengan kondisi lain sama, pelepasan gelembung lebih banyak di tempat terang. Ulangi pengamatan; hitungan ini bukan bukti bahwa semua jenis tumbuhan selalu menghasilkan jumlah yang sama."},{"type":"mini_check","stage":"abstract","question":"Apa nama zat warna hijau pada daun yang membantu menangkap cahaya untuk fotosintesis?","options":["Akar serabut","Batang kayu","Klorofil"],"correct_index":2,"feedback":"Hebat, kamu sudah mencoba! Tepat! Klorofil adalah zat warna hijau yang membantu menangkap energi cahaya untuk fotosintesis."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Fotosintesis menggunakan air dan karbon dioksida dengan bantuan cahaya untuk menghasilkan gula dan oksigen. Klorofil membantu menangkap cahaya. Ayo terapkan: Bersama pendamping, gambar alur air dari tanah ke daun dan beri label bahan, sumber energi, serta hasil fotosintesis. Tidak perlu menyimpan tanaman hidup di lemari tertutup."}],"blocks":[],"source_example":{"slug":"fotosintesis-tumbuhan-kelas-4","source_title":"Buku IPAS SD Kelas 4 Kurikulum Merdeka"},"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi"},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('7a01bb2b-08af-5466-9a9c-6db736a6bdb5'::uuid,'Proses tumbuhan hijau membuat makanannya sendiri dengan bantuan cahaya matahari disebut...','["Penguapan","Fotosintesis","Pencernaan","Pembekuan"]'::jsonb,'easy',1::smallint,'Fotosintesis adalah proses tumbuhan hijau membuat makanan dari air dan karbon dioksida dengan bantuan energi cahaya.'),
('e485dcdb-657a-55ff-b9d9-66f5beb45d66'::uuid,'Gas hasil fotosintesis yang juga dibutuhkan manusia untuk bernapas adalah...','["Karbon dioksida","Asap","Oksigen","Nitrogen"]'::jsonb,'easy',2::smallint,'Fotosintesis menghasilkan gula dan oksigen. Manusia memerlukan oksigen untuk bernapas; asap bukan hasil fotosintesis.'),
('f2fcf335-fd7f-51c3-b4bd-52c6353ee2b3'::uuid,'Rani membandingkan dua tanaman sejenis dengan ukuran awal, air dan tanah sama. Tanaman A mendapat cahaya, B berada di tempat gelap. Mengapa B lebih sulit membuat makanan melalui fotosintesis?','["B tidak perlu air lagi","B memperoleh makanan dari gelap","Akar B berubah menjadi makanan","B tidak mendapat cahaya yang diperlukan untuk fotosintesis"]'::jsonb,'medium',3::smallint,'Cahaya menyediakan energi untuk fotosintesis. Perbandingan ini menyamakan kondisi lain; gelap menghambat fotosintesis, tetapi layu saja tidak selalu menunjukkan satu penyebab.'),
('69438100-7f50-558f-9a3d-d83a2cfdeb76'::uuid,'Tanah pot Lala masih lembap. Bagian tumbuhan mana yang menyerap air dari tanah sebelum air diangkut lewat batang menuju daun?','["Akar","Bunga","Buah","Biji di buah"]'::jsonb,'medium',0::smallint,'Akar menyerap air dan mineral dari tanah. Air kemudian diangkut melalui batang menuju daun untuk membantu fotosintesis dan kebutuhan tumbuhan lainnya.'),
('fcb28832-2203-5460-ab13-45e15d6c5a32'::uuid,'Dua tumbuhan air sejenis diamati 5 menit dengan kondisi lain sama. Data gelembung: terang 18, redup 6, gelap 0. Kesimpulan mana paling sesuai dengan data?','["Gelap selalu membuat semua tumbuhan mati seketika","Pada percobaan ini, pelepasan gelembung paling banyak saat terang","Cahaya tidak berhubungan dengan hasil pengamatan","Semua tumbuhan pasti menghasilkan 18 gelembung"]'::jsonb,'hard',1::smallint,'Bandingkan 18, 6 dan 0: nilai terbesar muncul saat terang. Kesimpulan dibatasi pada percobaan ini; data tidak membuktikan semua tumbuhan selalu menghasilkan jumlah yang sama.'),
('df90526c-defb-53be-9796-01364286ae61'::uuid,'Tobi ingin menguji pengaruh cahaya terhadap fotosintesis. Rancangan mana paling membantu membedakan pengaruh cahaya dari pengaruh air?','["Tanaman terang disiram, tanaman gelap tidak disiram","Bandingkan kaktus besar dengan kecambah kecil di tempat berbeda","Dua tanaman sejenis berukuran awal sama, air dan tanah sama, tetapi pencahayaan berbeda","Ubah air, tanah dan cahaya sekaligus"]'::jsonb,'hard',2::smallint,'Ubah satu faktor, yaitu cahaya, sambil menyamakan faktor lain. Jika air dan jenis tanaman juga berbeda, kita sulit mengetahui faktor mana yang memengaruhi hasil.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT 'f0113139-5be1-560a-b42e-2554dbda24d5',s.id,'Gaya di Sekitar Kita: Otot, Gesek, Magnet','komik-ipa-kelas-4-bab-2',4,'B','Komik · Bab 2','sedang','published',25,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Gaya di Sekitar Kita: Otot, Gesek, Magnet. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Mobil mainan Tobi meluncur berbeda di kain dan meja. Sebuah magnet menarik penjepit kertas tetapi tidak semua benda logam. Ia mencari penjelasan yang mengikuti bukti, bukan nama benda saja."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel interaksi: dorongan/tarikan = gaya; permukaan bersentuhan = gesekan; kutub sejenis magnet menolak, berbeda menarik."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Gaya otot dan akibat gaya. Otot menghasilkan gaya saat kita mendorong, menarik atau memegang. Gaya dapat membuat benda mulai bergerak, mempercepat, memperlambat, berubah arah atau berubah bentuk. Tidak semua gaya menghasilkan gerak yang terlihat karena dapat seimbang. Menekan dinding tetap memberi gaya meskipun dinding tidak berpindah."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Mendorong mobil mainan dapat menambah kecepatannya. Dua dorongan berlawanan yang seimbang dapat membuat posisi tetap; ini bukan berarti tidak ada gaya."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Gaya gesek. Gesekan muncul pada permukaan bersentuhan dan cenderung menghambat gerak relatif. Besarnya dipengaruhi keadaan permukaan serta gaya tekan. Gesekan membantu berjalan dan mengerem, tetapi juga dapat menyebabkan panas atau keausan. Permukaan licin tidak berarti tanpa gesekan sama sekali."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Sol sepatu bertekstur membantu cengkeraman. Saat buku digeser di atas kain kasar, hambatannya dapat berbeda dibanding meja licin pada kondisi yang sebanding."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Gaya magnet. Magnet mempunyai kutub yang dapat tarik-menarik atau tolak-menolak: kutub sejenis menolak, berbeda menarik. Magnet menarik bahan tertentu seperti besi, bukan semua logam. Gaya magnet dapat bekerja tanpa sentuhan langsung pada jarak dekat. Jauhkan magnet kecil dari mulut serta perangkat atau implan yang sensitif sesuai arahan pendamping."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Penjepit kertas besi dapat tertarik, sedangkan kertas dan banyak benda aluminium tidak tertarik seperti besi. Kesimpulan harus menyebut bahan yang diuji, bukan semua logam."},{"type":"mini_check","stage":"abstract","question":"Benda tetap diam saat didorong dapat berarti …","options":["Gaya-gayanya seimbang","Tidak ada interaksi apa pun","Benda bukan materi"],"correct_index":0,"feedback":"Hebat, kamu sudah mencoba! Gaya dapat ada tanpa perpindahan yang terlihat."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Gaya dapat mengubah gerak/bentuk atau seimbang. Gesekan bermanfaat dan dapat menghambat; magnet memengaruhi bahan tertentu serta kutubnya. Ayo terapkan: Dengan benda ringan, bandingkan gerak buku kecil di dua alas sambil menjaga cara dorong serupa. Pendamping dapat menunjukkan magnet besar aman pada benda yang diketahui bahannya. Catat tertarik/tidak dan keterbatasan uji."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi"},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('a53ff298-63c6-5a9e-b799-8331a0b059b9'::uuid,'Dorongan dan tarikan disebut …','["Suhu","Volume","Gaya","Habitat"]'::jsonb,'easy',2::smallint,'Gaya merupakan interaksi dorong/tarik.'),
('1d8d27bd-6260-5f78-b711-06c7525ac594'::uuid,'Gesekan dapat membantu …','["Menghapus gravitasi","Membuat semua logam magnet","Mengubah batu jadi makanan","Berjalan tanpa mudah tergelincir"]'::jsonb,'easy',3::smallint,'Cengkeraman kaki/lantai memerlukan gesekan.'),
('3b077f45-7290-5268-9b5e-ef5d981e28a9'::uuid,'Sepatu membantu anak tidak mudah tergelincir terutama karena …','["Gesekan sol dan lantai","Tidak ada gaya sama sekali","Matahari berhenti","Semua lantai bermagnet"]'::jsonb,'medium',0::smallint,'Gesekan memberi cengkeraman; kondisi permukaan tetap memengaruhi keselamatan.'),
('da238083-1860-584e-bcd5-87e554254e51'::uuid,'Dua kutub utara magnet didekatkan. Keduanya cenderung …','["Selalu menarik","Tolak-menolak","Mencair","Menjadi air"]'::jsonb,'medium',1::smallint,'Kutub sejenis saling menolak; kutub berbeda saling menarik.'),
('de6d5200-e911-51e7-8368-20708bc9630b'::uuid,'Tabel uji magnet: besi tertarik, kayu tidak, aluminium tidak pada uji tersebut. Kesimpulan tepat …','["Semua logam pasti tertarik","Kayu selalu magnet kuat","Tidak semua bahan/logam tertarik seperti besi","Aluminium bukan materi"]'::jsonb,'hard',2::smallint,'Hasil mengingatkan bahwa sifat magnet bergantung bahan, bukan sekadar disebut logam.'),
('2d8e2d53-51f3-5c3e-84a8-4a56df36df73'::uuid,'Dua panah gaya pada benda sama besar dan berlawanan; benda tetap diam. Penjelasan tepat …','["Diam membuktikan tak ada gaya","Gaya selalu membuat berpindah","Benda tidak punya massa","Gaya dapat seimbang meski tetap ada"]'::jsonb,'hard',3::smallint,'Resultan gaya dapat nol; adanya gaya tidak selalu menghasilkan perubahan gerak yang terlihat.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '617654cf-7f23-59a7-a4b3-19370fbf5c57',s.id,'Cahaya dan Sifatnya & Bunyi','komik-ipa-kelas-5-bab-1',5,'C','Komik · Bab 1','sedang','published',25,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Cahaya dan Sifatnya & Bunyi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Tobi melihat pensil tampak bengkok di air dan mendengar bunyi penggaris bergetar. Kedua kejadian perlu penjelasan berbeda. Ia menggunakan model aman tanpa cahaya kuat atau bunyi keras."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel fenomena: cermin → pemantulan; pensil dalam air → pembiasan; penggaris bergetar → sumber bunyi. Cahaya dan bunyi berbeda kebutuhan medium."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Cahaya, bayangan dan bahan. Cahaya merambat lurus pada medium homogen dan dapat dihalangi benda sehingga membentuk bayangan. Bahan transparan meneruskan banyak cahaya, tembus cahaya meneruskan sebagian dengan hamburan, dan opak menghalangi sebagian besar. Benda terlihat ketika cahaya dari sumber atau pantulan masuk mata. Bukan mata yang memancarkan sinar untuk melihat."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Kaca bening memungkinkan melihat objek di baliknya; kertas karton memberi bayangan. Ketajaman bayangan bergantung juga ukuran sumber dan jarak, bukan hanya nama bahan."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Pemantulan dan pembiasan. Cahaya dapat dipantulkan oleh permukaan; cermin memberi pantulan teratur. Saat berpindah antara medium berbeda, arah dapat berubah karena pembiasan. Gunakan contoh pengamatan tanpa menyentuh kaca pecah. Pantulan cermin bukan benda kedua yang hidup; model garis membantu menjelaskan arah cahaya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Pensil dalam gelas air tampak bengkok karena pembiasan pada batas air/udara. Pensil sebenarnya tidak harus patah. Permukaan air juga dapat memantulkan cahaya."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Bunyi dari getaran dan medium. Bunyi dihasilkan sumber bergetar dan memerlukan medium seperti udara, air atau padat. Bunyi tidak merambat dalam ruang hampa seperti cahaya dapat merambat. Tinggi nada berkaitan frekuensi; keras-lembut berkaitan amplitudo/intensitas dan jarak. Lindungi pendengaran; jangan mencoba mendengar dengan menempelkan telinga ke benda berbahaya."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Penggaris plastik yang digetarkan pelan di tepi meja dapat berbunyi. Bagian bebas yang panjang dan pendek dapat menghasilkan nada berbeda, dengan pengawasan agar tidak terpental."},{"type":"mini_check","stage":"abstract","question":"Perbedaan penting bunyi dan cahaya adalah …","options":["Bunyi memerlukan medium, cahaya dapat melalui ruang hampa","Keduanya selalu perlu udara","Cahaya hanya di air"],"correct_index":0,"feedback":"Hebat, kamu sudah mencoba! Gelombang bunyi memerlukan materi sebagai medium."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Cahaya dapat dipantulkan dan dibiaskan serta membentuk bayangan. Bunyi berasal dari getaran dan memerlukan medium; jaga mata/telinga. Ayo terapkan: Amati bayangan kartu dengan cahaya ruangan dan pantulan cermin yang dipegang pendamping. Lalu ketuk wadah ringan sangat pelan dan catat getarannya. Bedakan sumber, medium dan penerima dalam sketsa."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi"},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('1e6689cc-a736-5a45-911f-e7d7c0298365'::uuid,'Buku terlihat karena …','["Mata menyinari buku","Buku harus berbunyi","Cahaya masuk mata dari pantulan buku","Udara menjadi warna"]'::jsonb,'easy',2::smallint,'Penglihatan memerlukan cahaya yang diterima mata.'),
('1a4e3de1-2f2e-59eb-8d3e-01694e7a8d63'::uuid,'Cermin menunjukkan …','["Pembekuan","Fotosintesis","Peresapan","Pemantulan cahaya"]'::jsonb,'easy',3::smallint,'Cahaya dipantulkan oleh permukaan cermin.'),
('cd936d96-6d15-5a41-a401-9e2b0a601aa8'::uuid,'Pensil utuh tampak bengkok saat sebagian berada dalam air. Penyebab yang sesuai …','["Pembiasan cahaya","Pensil pasti patah","Air selalu bermagnet","Fotosintesis"]'::jsonb,'medium',0::smallint,'Arah cahaya berubah pada batas medium, sehingga posisi tampak berbeda.'),
('7840469f-23ce-5be1-940a-9a971cca0996'::uuid,'Penggaris plastik digetarkan pelan dan terdengar bunyi. Sumber bunyinya …','["Warna penggaris","Getaran penggaris","Angka tertulis saja","Cahaya lampu saja"]'::jsonb,'medium',1::smallint,'Getaran sumber menimbulkan gangguan yang merambat melalui medium.'),
('ffd24136-2d5b-5a2b-ba1a-24b702f44e4c'::uuid,'Tabel model: A cahaya melalui ruang hampa; B bunyi melalui ruang hampa tanpa medium. Yang sesuai …','["B saja","Keduanya","A saja","Tidak ada cahaya bisa merambat"]'::jsonb,'hard',2::smallint,'Cahaya dapat merambat di ruang hampa; bunyi membutuhkan medium materi.'),
('39766ea5-dd70-5540-8fa5-4e6a2b09bfd3'::uuid,'Tabel bahan: kaca bening meneruskan banyak cahaya; karton menghalangi. Model penggunaan tepat …','["Karton pasti tembus pandang","Kaca tidak pernah meneruskan cahaya","Semua bahan identik","Karton dapat menjadi penghalang pembentuk bayangan"]'::jsonb,'hard',3::smallint,'Benda opak seperti karton menghalangi cahaya dan dapat membentuk bayangan; bentuk sumber/jarak juga berpengaruh.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '24d1580e-458b-5070-afb2-2e8821ce21f1',s.id,'Rantai Makanan & Jaring Ekosistem','komik-ipa-kelas-5-bab-2',5,'C','Komik · Bab 2','sedang','published',25,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Rantai Makanan & Jaring Ekosistem. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Peta kebun Tobi menunjukkan tumbuhan, pemakan tumbuhan dan pemangsa. Ia memberi arah panah dari makanan ke pemakan agar aliran bahan dan energi tidak terbalik."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Model rantai: rumput → belalang → katak → ular. Pengurai terkait sisa berbagai organisme; jaring sebenarnya dapat memiliki banyak jalur."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Produsen, konsumen dan pengurai. Produsen seperti tumbuhan hijau membuat bahan organik menggunakan energi. Konsumen memperoleh makanan dari organisme lain. Pengurai seperti banyak bakteri/jamur menguraikan sisa dan mengembalikan unsur ke lingkungan. Peran bergantung cara memperoleh bahan dan energi; satu organisme dapat memiliki hubungan makan beragam."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Padi sebagai produsen dapat dimakan belalang, belalang dimakan katak. Jamur/bakteri menguraikan sisa; mereka tidak muncul hanya pada akhir hidup satu rantai yang lurus."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Arah panah dan jaring makanan. Panah pada model ini menunjuk dari sumber makanan ke pemakan, menyatakan perpindahan bahan/energi. Satu hewan dapat memakan beberapa jenis dan dimakan lebih dari satu pemangsa, sehingga rantai saling terhubung. Jelaskan aturan panah agar tidak terbalik. Jangan memasukkan pasangan makan yang tidak cocok hanya agar diagram panjang."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Rumput → belalang → burung berarti belalang memakan rumput dan burung memakan belalang. Tambahan ulat dan pemangsa lain dapat membentuk jaring bila hubungan didukung sumber."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Keseimbangan, gangguan dan bukti. Perubahan satu populasi dapat memengaruhi yang lain, tetapi arah dan besarnya bergantung banyak hubungan. Hilangnya produsen mengurangi sumber energi dasar. Materi berputar melalui lingkungan dan organisme, sedangkan energi mengalir lalu menyebar sebagai panas; energi tidak berputar sama seperti materi. Gunakan kata dapat bila akibat belum pasti."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Jika pemangsa berkurang, mangsa dapat bertambah, tetapi makanan, penyakit dan habitat juga berpengaruh. Jangan menyatakan semua perubahan populasi mempunyai satu sebab saja."},{"type":"mini_check","stage":"abstract","question":"Satu populasi berubah, akibat pada populasi lain …","options":["Selalu sama di semua tempat","Perlu dinilai dari hubungan dan kondisi","Pasti tidak ada"],"correct_index":1,"feedback":"Hebat, kamu sudah mencoba! Jaring, makanan dan kondisi lain memengaruhi respons."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Produsen, konsumen dan pengurai saling terkait. Rantai adalah satu jalur, jaring banyak jalur. Perubahan perlu dinilai dengan konteks dan bukti. Ayo terapkan: Buat kartu organisme sawah dari sumber pendamping dan susun jaring makanan berpanah berlabel. Lepas satu kartu sebagai simulasi, lalu tulis dua kemungkinan dampak dan data apa yang perlu dicari, tanpa menangkap hewan."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi"},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('cf66cef9-9cfb-5ec5-8fef-34daf3575dae'::uuid,'Produsen dalam model kebun adalah …','["Kucing","Elang","Kursi","Tanaman hijau"]'::jsonb,'easy',3::smallint,'Tumbuhan hijau membuat bahan organik melalui fotosintesis.'),
('9426ccd1-e70a-5e8c-a5f7-8129f758c35f'::uuid,'Rumput → kelinci berarti …','["Kelinci memakan rumput","Rumput memakan kelinci","Rumput berjalan ke kelinci","Kelinci menjadi cahaya"]'::jsonb,'easy',0::smallint,'Panah mengarah dari makanan ke pemakan.'),
('f9f0ddb0-0029-5097-bfe4-52568c29a6fa'::uuid,'Dalam rumput → kelinci, arti panah adalah …','["Rumput memakan kelinci","Kelinci memperoleh bahan/energi dari rumput","Rumput berjalan ke kelinci","Kelinci membuat matahari"]'::jsonb,'medium',1::smallint,'Panah model ini menunjuk dari sumber makanan ke pemakan.'),
('f850895a-c2d4-5eb7-8e3f-823a95a7427a'::uuid,'Sisa organisme di kebun diuraikan banyak jamur dan bakteri. Peran ini disebut …','["Produsen yang selalu berfotosintesis","Benda mati","Pengurai","Satelit"]'::jsonb,'medium',2::smallint,'Pengurai membantu memecah sisa dan mengembalikan unsur ke lingkungan.'),
('d254fc27-9360-5f4e-bae8-d80906a4195a'::uuid,'Jaring model: padi→belalang; padi→tikus; belalang→burung; tikus→ular. Pernyataan yang didukung …','["Burung pasti memakan ular","Tikus memakan burung pada model","Panah tidak punya arti","Padi menjadi sumber makanan bagi dua konsumen pada model"]'::jsonb,'hard',3::smallint,'Ada dua panah keluar dari padi menuju belalang dan tikus; hubungan lain tidak boleh dikarang.'),
('73a70d77-b449-5934-8701-b37bbad85ce8'::uuid,'Pada model sederhana pemangsa berkurang, lalu mangsa dapat bertambah. Kesimpulan ilmiah …','["Itu kemungkinan; makanan, penyakit dan habitat juga perlu dinilai","Pasti sama di semua ekosistem","Semua mangsa langsung hilang","Tidak perlu data lanjutan"]'::jsonb,'hard',0::smallint,'Jaring dan faktor lingkungan membuat akibat tidak selalu satu pola pasti.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '3b19b94c-54e9-56ef-b940-7ac21f66f20a',s.id,'Sistem Rangka, Sendi, & Saraf Manusia','komik-ipa-kelas-6-bab-1',6,'C','Komik · Bab 1','sedang','published',25,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Sistem Rangka, Sendi, & Saraf Manusia. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Tobi membuat model karton lengan dan menggambar jalur informasi. Ia ingin menjelaskan kerja sama tulang, sendi, otot dan saraf tanpa memaksa gerakan atau menilai kesehatan teman."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Diagram: informasi indra → sistem saraf → sinyal ke otot → tarikan pada tulang melalui sendi. Model adalah penyederhanaan, bukan alat diagnosis."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Rangka, perlindungan dan kerja otot. Rangka membantu menopang bentuk, melindungi organ dan menjadi tempat kerja otot. Tulang mempunyai jaringan hidup, bukan batang mati. Otot menarik tulang melalui hubungan yang sesuai; otot tidak mendorong tulang seperti tongkat. Pasangan/kelompok otot bekerja terkoordinasi untuk arah gerak berbeda."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tengkorak melindungi otak dan rangka dada membantu melindungi organ dada. Ketika siku ditekuk, kelompok otot tertentu memendek sementara kelompok lain menyesuaikan; gerak bukan kerja tulang sendirian."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Sendi dan kemungkinan gerak. Sendi adalah hubungan antar tulang dengan bentuk dan rentang gerak berbeda. Sendi engsel seperti siku terutama memungkinkan gerak menekuk-meluruskan, sedangkan sendi peluru seperti bahu memungkinkan arah lebih beragam. Beberapa hubungan tulang hampir tidak bergerak. Model sederhana tidak mencakup seluruh detail anatomi."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Pintu memberi analogi engsel, tetapi sendi manusia bukan engsel logam. Jangan memutar siku seperti bahu; bentuk dan jaringan pembatasnya berbeda."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Saraf, otak dan respons. Sistem saraf menerima informasi, mengolah dan mengirim sinyal. Otak, sumsum tulang belakang dan saraf tepi saling berkaitan. Respons tertentu cepat melalui jalur refleks, tetapi keseluruhan koordinasi tetap kompleks. Kelainan gerak atau rasa tidak dapat didiagnosis dari permainan kelas; laporkan keluhan kepada pendamping/tenaga kesehatan."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Ketika melihat bola mendekat, informasi penglihatan membantu tubuh menyiapkan gerak. Respons tiap orang dipengaruhi banyak keadaan; satu uji reaksi tidak menilai kecerdasan atau kesehatan seseorang."},{"type":"mini_check","stage":"abstract","question":"Jika gerak terasa sakit, tindakan tepat …","options":["Memaksa lebih jauh","Berhenti dan memberi tahu pendamping","Menguji dengan pukulan"],"correct_index":1,"feedback":"Hebat, kamu sudah mencoba! Jangan memaksakan gerak atau membuat diagnosis dari aktivitas belajar."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Rangka menopang/melindungi, sendi memungkinkan gerak tertentu, otot menghasilkan tarikan dan saraf mengoordinasi informasi serta respons. Ayo terapkan: Buat model dua batang karton berengsel aman dan bandingkan dengan gambar sendi bahu. Gambar panah informasi dari indra ke sistem saraf lalu respons otot. Gerak hanya sukarela, ringan dan boleh diganti pengamatan model."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('248662ee-58d3-56f0-92ba-e93dfe257f14'::uuid,'Organ yang dilindungi tengkorak adalah …','["Lambung","Lutut","Usus","Otak"]'::jsonb,'easy',3::smallint,'Tengkorak melindungi otak.'),
('d0425557-1f41-547b-a4c7-3401dc261ae5'::uuid,'Sendi siku terutama menyerupai …','["Engsel","Peluru bebas ke semua arah","Paku tanpa gerak selalu","Roda penuh"]'::jsonb,'easy',0::smallint,'Siku terutama memungkinkan menekuk dan meluruskan.'),
('c43a0520-70af-59bb-b235-d232ef5879fe'::uuid,'Pada model lengan, tulang bergerak terutama karena …','["Tulang memendek sendiri seperti otot","Tarikan otot yang terkoordinasi","Warna kulit","Nama sendi"]'::jsonb,'medium',1::smallint,'Otot menarik tulang dan geraknya dikoordinasi sistem tubuh.'),
('cb023e9c-8316-5583-96fb-4329ab64eb52'::uuid,'Tobi membandingkan siku dan bahu. Pernyataan sesuai …','["Semua sendi bebas diputar sama","Siku perlu dipaksa seperti bahu","Rentang geraknya berbeda karena bentuk sendinya berbeda","Sendi tidak memengaruhi gerak"]'::jsonb,'medium',2::smallint,'Siku terutama engsel, bahu mempunyai gerak lebih beragam. Jangan memaksa posisi.'),
('e4161bba-8aba-5bd1-9881-32e9f660048d'::uuid,'Tabel fungsi: A=rangka melindungi/menopang; B=saraf menerima dan mengirim informasi. Model hubungan tepat …','["Saraf menggantikan tulang","Tulang saja cukup untuk semua gerak","Otot tidak berperan","Keduanya bekerja bersama otot dan sendi"]'::jsonb,'hard',3::smallint,'Gerak/koordinasi memerlukan kerja sama beberapa sistem, bukan fungsi satu bagian saja.'),
('5b117ef3-8e0e-571a-b7c9-f49cf54b1226'::uuid,'Dalam permainan reaksi, satu anak lebih lambat pada satu percobaan. Kesimpulan tepat …','["Belum dapat menilai kesehatan atau kecerdasannya","Pasti gangguan saraf","Pasti tidak cerdas","Harus dipaksa mengulang sampai sakit"]'::jsonb,'hard',0::smallint,'Respons dipengaruhi banyak kondisi; permainan kelas bukan pemeriksaan kesehatan.')
INSERT INTO public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) SELECT '4d3a84aa-709d-5301-83fe-80e4ac18fdf7',s.id,'Sistem Tata Surya, Rotasi, & Revolusi Bumi','komik-ipa-kelas-6-bab-2',6,'C','Komik · Bab 2','sedang','published',25,'{"character":"tobi","summary":"Pulau Eksplora bersama Ilmuwan Tobi: Sistem Tata Surya, Rotasi, & Revolusi Bumi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":"","scenes":[{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"kaget","stage":"concrete","text":"Tobi memegang bola bumi sementara lampu model tetap di satu tempat. Ia memutar bola pada poros lalu menggerakkannya mengelilingi lampu untuk membedakan dua gerak."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Tabel gerak: rotasi bumi ≈ satu hari → siang/malam; revolusi ≈ satu tahun. Urutan planet: Merkurius, Venus, Bumi, Mars, Jupiter, Saturnus, Uranus, Neptunus."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Matahari, planet dan satelit. Matahari adalah bintang pusat tata surya. Delapan planet menurut urutan dari matahari ialah Merkurius, Venus, Bumi, Mars, Jupiter, Saturnus, Uranus dan Neptunus. Planet tidak memancarkan cahaya tampak sendiri seperti bintang; kita melihat pantulan. Bulan adalah satelit alami bumi; Pluto diklasifikasikan planet katai, bukan salah satu delapan planet utama."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Bumi mengorbit matahari, bulan mengorbit bumi, dan keduanya ikut bergerak dalam tata surya. Gambar yang menaruh semua planet berdekatan bukan gambaran jarak nyata."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Rotasi dan akibatnya. Rotasi adalah putaran benda pada poros. Bumi berotasi sekitar sekali sehari, sehingga bagian permukaan bergantian menghadap matahari. Ini menjelaskan siang-malam dan gerak tampak harian matahari. Perbedaan waktu antarwilayah berkaitan rotasi serta kesepakatan zona waktu. Matahari tidak benar-benar mengelilingi bumi sekali tiap hari."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Pada model bola berputar di depan lampu, satu titik berpindah dari terang ke gelap. Lampu tetap menjadi model matahari, bukan berkeliling mengitari bola untuk menjelaskan rotasi."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"berpikir","stage":"abstract","text":"Revolusi dan kemiringan sumbu. Revolusi adalah gerak mengelilingi benda lain; bumi mengelilingi matahari sekitar satu tahun. Kemiringan sumbu bumi bersama revolusi berkaitan dengan perubahan musim dan lama siang di berbagai lintang. Musim bukan terutama akibat bumi bergantian sangat dekat dan jauh dari matahari. Indonesia mempunyai pola musim yang juga dipengaruhi sirkulasi angin/laut dan letak geografis."},{"type":"comic_panel","stage":"representational","image_url":"/images/lessons/default-illustration.webp","caption":"Dua belahan bumi dapat mengalami musim berbeda pada waktu sama. Model musim perlu mempertahankan arah sumbu saat bumi bergerak, dan menjelaskan bahwa skalanya disederhanakan."},{"type":"mini_check","stage":"abstract","question":"Penyebab utama perbedaan musim lintang menengah adalah …","options":["Matahari dimatikan","Jarak bumi satu-satunya","Kemiringan sumbu bersama revolusi"],"correct_index":2,"feedback":"Hebat, kamu sudah mencoba! Kemiringan mengubah sudut dan lama penyinaran sepanjang orbit."},{"type":"dialog","speaker":"Ilmuwan Tobi","emotion":"senang","stage":"abstract","text":"Matahari bintang, bumi planet, bulan satelit. Rotasi sekitar sehari; revolusi sekitar setahun. Model perlu menjelaskan skala dan kemiringan sumbu. Ayo terapkan: Gunakan kartu delapan planet untuk urutan. Pendamping memakai bola dan lampu aman untuk model rotasi/revolusi. Labeli gerak, waktu kira-kira dan batas model; jangan menatap lampu kuat atau matahari."}],"blocks":[],"package_id":"seed-materi-lengkap-cra-v1","enrichment":false,"review_status":"needs_teacher_review","curriculum_note":"Cakupan aplikasi, bukan daftar isi resmi nasional; perlu review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/"}]}'::jsonb FROM public.subjects s WHERE s.slug='ipa' ON CONFLICT (subject_id, grade, slug) DO UPDATE SET title=EXCLUDED.title,phase=EXCLUDED.phase,chapter=EXCLUDED.chapter,difficulty=EXCLUDED.difficulty,status='published',duration=EXCLUDED.duration,content=EXCLUDED.content WHERE (lessons.title,lessons.phase,lessons.chapter,lessons.difficulty,lessons.status,lessons.duration,lessons.content) IS DISTINCT FROM (EXCLUDED.title,EXCLUDED.phase,EXCLUDED.chapter,EXCLUDED.difficulty,'published',EXCLUDED.duration,EXCLUDED.content);
INSERT INTO public.questions(id,lesson_id,prompt,options,difficulty,status,correct_option,explanation) SELECT v.id,l.id,v.prompt,v.options,v.difficulty,'published',v.correct_option,v.explanation FROM (VALUES
('7cce7f3d-7c48-5772-a95e-056ba0786896'::uuid,'Benda pusat tata surya adalah …','["Matahari","Bulan","Bumi","Jupiter"]'::jsonb,'easy',0::smallint,'Matahari adalah bintang pusat tata surya.'),
('764eb90f-9d8f-5ecd-9906-0bc40ef8bcd7'::uuid,'Jumlah planet utama tata surya adalah …','["7","8","9","12"]'::jsonb,'easy',1::smallint,'Pluto termasuk planet katai, bukan delapan planet utama.'),
